        '    if chat_id is None or message_id is None:\n'
        '        return 0\n'
        '    key = (int(chat_id), int(message_id))\n'
        '    with SCREEN_REVISION_LOCK:\n'
        '        return int(SCREEN_REVISION.get(key) or 0)\n'
        '\n'
        '\n'
        'def prune_stale_contexts(now_ts: Optional[float] = None, max_ui_age_seconds: int = 3600) -> int:\n'
        '    """Evict expired ephemeral Telegram UI states and stale runtime buyer contexts from memory."""\n'
        '    now_value = float(now_ts if now_ts is not None else time.time())\n'
        '    cutoff = now_value - max(60, int(max_ui_age_seconds))\n'
        '    buyer_cutoff = now_value - 7 * 86400\n'
        '    removed = 0\n'
        '\n'
        '    with CONTEXT_LOCK:\n'
        '        for mapping in (\n'
        '            LOT_INPUT_STATES,\n'
        '            UI_INPUT_STATES,\n'
        '            LOT_CARD_CONTEXT,\n'
        '            SEARCH_RESULT_CONTEXT,\n'
        '            ANALYTICS_VIEW_MODES,\n'
        '        ):\n'
        '            for key in list(mapping.keys()):\n'
        '                ctx = mapping.get(key)\n'
        '                if not isinstance(ctx, dict):\n'
        '                    continue\n'
        '                created_ts = ctx.get("created_ts")\n'
        '                if created_ts is None:\n'
        '                    continue\n'
        '                try:\n'
        '                    if float(created_ts) < cutoff:\n'
        '                        mapping.pop(key, None)\n'
        '                        removed += 1\n'
        '                except (TypeError, ValueError):\n'
        '                    mapping.pop(key, None)\n'
        '                    removed += 1\n'
        '\n'
        '        for key in list(waiting_for_link.keys()):\n'
        '            ctx = waiting_for_link.get(key)\n'
        '            if not isinstance(ctx, dict):\n'
        '                continue\n'
        '            created_ts = ctx.get("created_ts") or ctx.get("updated_ts")\n'
        '            if created_ts is None:\n'
        '                continue\n'
        '            try:\n'
        '                if float(created_ts) < buyer_cutoff:\n'
        '                    waiting_for_link.pop(key, None)\n'
        '                    removed += 1\n'
        '            except (TypeError, ValueError):\n'
        '                waiting_for_link.pop(key, None)\n'
        '                removed += 1\n'
        '\n'
        '        while len(BUYER_ORDER_SELECTION) > 5000:\n'
        '            oldest_key = next(iter(BUYER_ORDER_SELECTION))\n'
        '            BUYER_ORDER_SELECTION.pop(oldest_key, None)\n'
        '            removed += 1\n'
        '\n'
        '        for key in list(DELETE_CONFIRM_GRACE_UNTIL.keys()):\n'
        '            try:\n'
        '                if float(DELETE_CONFIRM_GRACE_UNTIL.get(key) or 0.0) < now_value:\n'
        '                    DELETE_CONFIRM_GRACE_UNTIL.pop(key, None)\n'
        '                    removed += 1\n'
        '            except (TypeError, ValueError):\n'
        '                DELETE_CONFIRM_GRACE_UNTIL.pop(key, None)\n'
        '                removed += 1\n'
        '\n'
        '    return removed\n'
        '\n'
        '\n'
        'def clear_memory_contexts() -> None:\n'
        '    """Reset in-memory buyer and Telegram UI wizard states."""\n'
        '    config.clear()\n'
        '    lot_mapping.clear()\n'
        '    with CONTEXT_LOCK:\n'
        '        for container in (\n'
        '            waiting_for_link,\n'
        '            BUYER_ORDER_SELECTION,\n'
        '            LOT_PAGE_CONTEXT,\n'
        '            WEBSITE_PAGE_CONTEXT,\n'
        '            LOT_INPUT_STATES,\n'
        '            LOT_CARD_CONTEXT,\n'
        '            UI_INPUT_STATES,\n'
        '            SEARCH_RESULT_CONTEXT,\n'
        '            ANALYTICS_VIEW_MODES,\n'
        '            DELETE_CONFIRM_GRACE_UNTIL,\n'
        '            CALLBACK_TOKENS,\n'
        '        ):\n'
        '            container.clear()\n'
        '    with SCREEN_REVISION_LOCK:\n'
        '        SCREEN_REVISION.clear()\n'
        '\n'
        '\n'
