        '        PANEL_BALANCE_CACHE["timestamp"] = 0.0\n'
        '        inflight = PANEL_BALANCE_CACHE.get("inflight")\n'
        '        if isinstance(inflight, dict):\n'
        '            inflight.clear()\n'
        '        else:\n'
        '            PANEL_BALANCE_CACHE["inflight"] = {}\n'
        '        services_map = PANEL_BALANCE_CACHE.get("services")\n'
        '        if isinstance(services_map, dict):\n'
