        '\n'
        'def _upsert_buyer_flow_order_record(\n'
        '    chat_id: int,\n'
        '    buyer_id: Any,\n'
        '    buyer_username: Any,\n'
        '    order_id_funpay: str,\n'
        '    lot_title: str,\n'
