        '    state: str = BUYER_STATE_WAITING_LINK,\n'
        '    saved_link: Optional[str] = None,\n'
        '    lot_key: Optional[str] = None,\n'
        ') -> bool:\n'
        '    """Create or update a FunPay order record and its buyer-flow runtime state atomically."""\n'
        '    order_id_str = str(order_id_funpay)\n'
        '    now_str_val = rt.now_str()\n'
        '    with ORDERS_LOCK:\n'
        '        base = db_orders.get_order(order_id_str) or {}\n'
        '        if base:\n'
        '            base_state = _get_buyer_flow_state(base)\n'
        '            stop_reason = str(base.get("status_stop_reason") or "").strip().lower()\n'
        '            panel_status_val = str(base.get("panel_status") or "").strip().lower()\n'
        '            protected_states = {\n'
        '                BUYER_STATE_REFUNDED,\n'
        '                BUYER_STATE_PANEL_CREATED,\n'
        '                BUYER_STATE_COMPLETED,\n'
        '                BUYER_STATE_FAILED,\n'
        '                BUYER_STATE_WAITING_CONFIRM,\n'
        '                BUYER_STATE_LINK_PAUSED,\n'
        '            }\n'
        '            if (\n'
        '                _is_order_refundedish(base)\n'
        '                or _has_panel_order(base)\n'
        '                or bool(base.get("panel_add_submitted"))\n'
        '                or panel_status_val == "manual_check"\n'
        '                or stop_reason in ("panel_add_in_flight", "transport_error_after_add", "persist_failed_after_add")\n'
        '                or base_state in protected_states\n'
        '            ):\n'
        '                return False\n'
        '\n'
        '        created_at = int(safe_float(base.get("created_at"), time.time()))\n'
        '        resolved_lot_key = lot_key if lot_key not in (None, "") else base.get("lot_key")\n'
        '        resolved_funpay_status = (\n'
