        '            "status": base.get("status") or "pending",\n'
        '            "customer_url": effective_saved_link or base.get("customer_url") or "",\n'
        '        }\n'
        '        merged = dict(base)\n'
        '        merged.update(record_update)\n'
        '        if resolved_lot_key not in (None, ""):\n'
        '            merged["lot_key"] = resolved_lot_key\n'
