        'def _save_waiting_context(data: Dict, state: Optional[str] = None, saved_link_marker: Any = "__keep__") -> None:\n'
        '    if not isinstance(data, dict):\n'
        '        return\n'
        '    order_id = str(data.get("order_id_funpay") or data.get("order_id") or "")\n'
        '    if not order_id:\n'
        '        return\n'
        '    if state:\n'
        '        data["state"] = state\n'
        '        data["step"] = _step_from_state(state)\n'
        '    else:\n'
        '        state = data.get("state") or _state_from_step(data.get("step"))\n'
        '    fields: Dict[str, Any] = {"buyer_flow_state": state, "updated_at": rt.now_str()}\n'
        '    if saved_link_marker != "__keep__":\n'
        '        fields["saved_link"] = saved_link_marker\n'
        '        if saved_link_marker in (None, ""):\n'
        '            data.pop("link", None)\n'
        '        else:\n'
        '            data["link"] = saved_link_marker\n'
        '    elif data.get("link"):\n'
        '        fields["saved_link"] = data.get("link")\n'
        '    update_order_fields(order_id, **fields)\n'
        '\n'
        '\n'
        'def _build_waiting_context_from_order(order_record: Dict) -> Optional[Dict[str, Any]]:\n'
        '    if not isinstance(order_record, dict):\n'
        '        return None\n'
        '    order_id = str(order_record.get("order_id") or "")\n'
        '    if not order_id:\n'
        '        return None\n'
        '    state = _get_buyer_flow_state(order_record)\n'
        '    now_ts = time.time()\n'
        '    raw_created = order_record.get("created_at")\n'
        '    try:\n'
        '        created_ts = float(raw_created) if raw_created not in (None, "") else now_ts\n'
        '    except (TypeError, ValueError):\n'
        '        created_ts = now_ts\n'
        '    if created_ts <= 0:\n'
        '        created_ts = now_ts\n'
        '    return {\n'
        '        "buyer_id": order_record.get("buyer_id"),\n'
        '        "chat_id": order_record.get("chat_id"),\n'
        '        "buyer_username": order_record.get("buyer_username") or "",\n'
        '        "service_id": order_record.get("service_id"),\n'
        '        "real_amount": int(order_record.get("quantity") or order_record.get("total_quantity") or 0),\n'
        '        "order_id_funpay": order_id,\n'
        '        "price": order_record.get("summa") or order_record.get("order_price") or 0,\n'
        '        "service_number": order_record.get("service_number", 1),\n'
        '        "lot_key": order_record.get("lot_key"),\n'
        '        "lot_title": order_record.get("lot_title") or order_record.get("service_name") or "",\n'
        '        "state": state,\n'
        '        "step": _step_from_state(state),\n'
        '        "link": order_record.get("saved_link") or order_record.get("customer_url") or "",\n'
        '        "created_ts": created_ts,\n'
        '        "updated_ts": now_ts,\n'
        '    }\n'
        '\n'
        '\n'
        'def _transition_waiting_state(\n'
        '    ctx: Dict,\n'
        '    order_id: str,\n'
        '    buyer_id: Any,\n'
        '    chat_id: Any,\n'
        '    state: str,\n'
        '    saved_link_marker: Any = "__keep__",\n'
        '    select_order: bool = True,\n'
        ') -> None:\n'
        '    """Update waiting context, persist buyer flow state, and update active selection."""\n'
        '    local_ctx = dict(ctx)\n'
        '    now_ts = time.time()\n'
        '    local_ctx.setdefault("created_ts", now_ts)\n'
        '    local_ctx["updated_ts"] = now_ts\n'
        '    _save_waiting_context(local_ctx, state=state, saved_link_marker=saved_link_marker)\n'
        '    with rt.CONTEXT_LOCK:\n'
        '        rt.waiting_for_link[order_id] = dict(local_ctx)\n'
        '    ctx.clear()\n'
        '    ctx.update(local_ctx)\n'
        '    if select_order:\n'
        '        _set_selected_order_for_buyer(buyer_id, chat_id, order_id)\n'
        '    else:\n'
        '        _clear_selected_order_for_buyer(buyer_id, chat_id)\n'
        '\n'
        '\n'
        'def _set_selected_order_for_buyer(buyer_id: Any, chat_id: Any, order_id: Any) -> None:\n'
        '    if order_id not in (None, ""):\n'
        '        with rt.CONTEXT_LOCK:\n'
        '            rt.BUYER_ORDER_SELECTION[_buyer_selection_key(buyer_id, chat_id)] = str(order_id)\n'
        '\n'
        '\n'
        'def _clear_selected_order_for_buyer(buyer_id: Any, chat_id: Any) -> None:\n'
        '    with rt.CONTEXT_LOCK:\n'
        '        rt.BUYER_ORDER_SELECTION.pop(_buyer_selection_key(buyer_id, chat_id), None)\n'
        '\n'
        '\n'
        'def _get_buyer_orders(buyer_id: Any, chat_id: Any) -> List[Dict]:\n'
        '    result = [\n'
        '        order_record for order_record in load_orders_data()\n'
        '        if isinstance(order_record, dict) and _buyer_owns_order(order_record, buyer_id, chat_id)\n'
        '    ]\n'
        '    result.sort(key=lambda item: safe_float(item.get("created_at"), 0.0), reverse=True)\n'
        '    return result\n'
        '\n'
        '\n'
        'def _resolve_buyer_order_for_action(\n'
        '    c: "Cardinal",\n'
        '    buyer_id: Any,\n'
        '    chat_id: Any,\n'
        '    raw_ref: Optional[str],\n'
        '    command_name: str,\n'
        ') -> Optional[Dict]:\n'
        '    records = _get_buyer_orders(buyer_id, chat_id)\n'
        '    if raw_ref:\n'
        '        for order_record in records:\n'
        '            if _matches_order_ref(order_record.get("order_id"), raw_ref):\n'
        '                return order_record\n'
        '        _send_buyer_message(c, chat_id, _format_order_not_found_for_buyer(raw_ref, records, command_name=command_name))\n'
        '        return None\n'
        '\n'
        '    active = [\n'
        '        r for r in records\n'
        '        if _get_buyer_flow_state(r) in BUYER_ACTIVE_PRE_PANEL_STATES\n'
        '        and not _has_panel_order(r)\n'
        '        and not _is_order_refundedish(r)\n'
        '    ]\n'
        '    if command_name in ("!ссылка", "!отмена"):\n'
        '        if len(active) == 1:\n'
        '            return active[0]\n'
        '        if len(active) > 1:\n'
        '            _send_buyer_message(c, chat_id, _format_short_order_list(active, command_name=command_name))\n'
        '            return None\n'
        '        _send_buyer_message(c, chat_id, ORDER_NOT_FOUND_TEXT)\n'
        '        return None\n'
        '\n'
        '    if len(records) == 1:\n'
        '        return records[0]\n'
        '    if records:\n'
        '        _send_buyer_message(c, chat_id, _format_short_order_list(records, command_name=command_name))\n'
        '        return None\n'
        '    _send_buyer_message(c, chat_id, "У вас пока нет SMM-заказов.")\n'
        '    return None\n'
        '\n'
        '\n'
        'def _buyer_owns_order(order_record: Dict, buyer_id: Any, chat_id: Any) -> bool:\n'
        '    if not isinstance(order_record, dict):\n'
        '        return False\n'
        '    buyer_match = buyer_id not in (None, "") and str(order_record.get("buyer_id")) == str(buyer_id)\n'
        '    chat_match = chat_id not in (None, "") and str(order_record.get("chat_id")) == str(chat_id)\n'
        '    return bool(buyer_match or chat_match)\n'
        '\n'
        '\n'
        '_buyer_can_access_order = _buyer_owns_order\n'
        '\n'
        '\n'
        'def _handle_buyer_smm_command(c: "Cardinal", msg_text: str, buyer_id: Any, chat_id: int) -> bool:\n'
        '    if not re.match(r"^!(?:смм|smm)\\s*$", msg_text.strip(), re.IGNORECASE):\n'
        '        return False\n'
        '    _send_buyer_message(c, chat_id, _format_buyer_smm_orders(_get_buyer_orders(buyer_id, chat_id)[:5]))\n'
        '    return True\n'
        '\n'
        '\n'
        'def _handle_buyer_commands_command(c: "Cardinal", msg_text: str, buyer_id: Any, chat_id: int) -> bool:\n'
        '    if not re.match(r"^!(?:команды|help|помощь)\\s*$", msg_text.strip(), re.IGNORECASE):\n'
        '        return False\n'
        '    cfg = load_config()\n'
