        '            _send_buyer_message(c, chat_id, f"▶️ Ожидание ссылки возобновлено.\\n\\n🧾 Заказ: #{order_id}\\n\\nОтправьте ссылку для запуска заказа.\\nСсылка должна начинаться с:\\nhttps://")\n'
        '            return True\n'
        '        if state == BUYER_STATE_WAITING_CONFIRM:\n'
        '            _transition_waiting_state(ctx, order_id, buyer_id, chat_id, BUYER_STATE_WAITING_LINK, saved_link_marker=None)\n'
        '            _send_buyer_message(c, chat_id, f"Текущая ссылка сброшена.\\n\\n🧾 Заказ: #{order_id}\\n\\nОтправьте новую ссылку.\\nСсылка должна начинаться с:\\nhttps://")\n'
        '            return True\n'
        '        if state == BUYER_STATE_WAITING_LINK:\n'
        '            if raw_ref:\n'
        '                _transition_waiting_state(ctx, order_id, buyer_id, chat_id, BUYER_STATE_WAITING_LINK, select_order=True)\n'
        '                _send_buyer_message(c, chat_id, "Отправьте ссылку для запуска заказа.")\n'
        '                return True\n'
        '            _transition_waiting_state(ctx, order_id, buyer_id, chat_id, BUYER_STATE_LINK_PAUSED, saved_link_marker=None, select_order=False)\n'
        '            _send_buyer_message(c, chat_id, f"⏸ Ожидание ссылки приостановлено.\\n\\n🧾 Заказ: #{order_id}\\n\\nКогда будете готовы отправить ссылку:\\n!ссылка {order_id}")\n'
        '            return True\n'
        '        _send_buyer_message(c, chat_id, "Отправьте ссылку для запуска заказа.")\n'
        '        return True\n'
        '\n'
        '\n'
        'def _is_post_panel_or_refunded(order_record: Dict) -> bool:\n'
        '    state = _get_buyer_flow_state(order_record)\n'
        '    return _has_panel_order(order_record) or state in (\n'
        '        BUYER_STATE_PANEL_CREATED, BUYER_STATE_COMPLETED, BUYER_STATE_FAILED, BUYER_STATE_REFUNDED\n'
        '    )\n'
        '\n'
        '\n'
        'def _can_buyer_refund_pre_panel(c: "Cardinal", order_record: Dict, buyer_id: Any, chat_id: Any) -> Tuple[bool, Dict]:\n'
        '    if not isinstance(order_record, dict):\n'
        '        return False, {}\n'
        '\n'
        '    order_id = str(order_record.get("order_id") or order_record.get("order_id_funpay") or "")\n'
        '    if not order_id:\n'
        '        return False, order_record\n'
        '\n'
        '    latest = get_order_data(order_id) or order_record\n'
        '    if not _buyer_owns_order(latest, buyer_id, chat_id) or _is_post_panel_or_refunded(latest):\n'
        '        return False, latest\n'
        '\n'
        '    # Force-check FunPay before any refund attempt. If the check is unavailable, do not refund.\n'
        '    result = _fetch_funpay_status_via_cardinal(c, order_id) if c else {"ok": False, "error": "no_cardinal"}\n'
        '    if not result.get("ok"):\n'
        '        rt.logger.warning(f"BUYER CANCEL SAFETY BLOCKED: order=#{order_id}, reason=funpay_force_check_failed, detail={result.get(\'detail\') or result.get(\'error\')}")\n'
        '        return False, latest\n'
        '\n'
        '    funpay_status = _normalize_funpay_status(result.get("funpay_status"))\n'
        '    if funpay_status:\n'
        '        fields: Dict[str, Any] = {"funpay_status": funpay_status, "funpay_status_checked_at": rt.now_str()}\n'
        '        if funpay_status in ("refunded", "partially_refunded"):\n'
        '            fields.update({"buyer_flow_state": BUYER_STATE_REFUNDED, "saved_link": None, "updated_at": rt.now_str()})\n'
        '            with rt.CONTEXT_LOCK:\n'
        '                rt.waiting_for_link.pop(order_id, None)\n'
        '        update_order_fields(order_id, **fields)\n'
        '        latest = get_order_data(order_id) or latest\n'
        '\n'
        '    if funpay_status != "open":\n'
        '        rt.logger.warning(f"BUYER CANCEL SAFETY BLOCKED: order=#{order_id}, reason=funpay_status_{funpay_status}")\n'
        '        return False, latest\n'
        '\n'
        '    return (not _is_post_panel_or_refunded(latest)), latest\n'
        '\n'
        '\n'
        'def _handle_buyer_cancel_command(c: "Cardinal", msg_text: str, buyer_id: Any, chat_id: int) -> bool:\n'
        '    match = re.match(r"^!отмена(?:\\s+(.+))?$", msg_text.strip(), re.IGNORECASE)\n'
        '    if not match:\n'
