        '    order_record = _resolve_buyer_order_for_action(c, buyer_id, chat_id, raw_ref, command_name="!отмена")\n'
        '    if not order_record:\n'
        '        return True\n'
        '    order_id = str(order_record.get("order_id"))\n'
        '    with rt.get_order_lock(order_id):\n'
        '        fresh_record = get_order_data(order_id) or order_record\n'
        '        allow_buyer_cancel = bool(load_config().get("allow_buyer_cancel_before_panel_order", False))\n'
        '        if not allow_buyer_cancel:\n'
        '            if _apply_refund_gate(c, fresh_record, notify_chat_id=chat_id, force_check=True):\n'
        '                return True\n'
        '        elif _is_order_refundedish(fresh_record):\n'
        '            if _apply_refund_gate(c, fresh_record, notify_chat_id=chat_id, force_check=False):\n'
        '                return True\n'
        '\n'
        '        state = _get_buyer_flow_state(fresh_record)\n'
        '        if _has_panel_order(fresh_record) or state in (BUYER_STATE_PANEL_CREATED, BUYER_STATE_COMPLETED, BUYER_STATE_FAILED):\n'
        '            _send_buyer_message(c, chat_id, "Заказ уже передан в работу.\\nАвтоматическая отмена недоступна.")\n'
        '            return True\n'
