        '\n'
        '        if allow_buyer_cancel:\n'
        '            can_refund, fresh_order = _can_buyer_refund_pre_panel(c, fresh_record, buyer_id, chat_id)\n'
        '            if not can_refund:\n'
        '                if _is_order_refundedish(fresh_order):\n'
        '                    _apply_refund_gate(c, fresh_order, notify_chat_id=chat_id, force_check=False)\n'
        '                elif _is_post_panel_or_refunded(fresh_order):\n'
        '                    _send_buyer_message(c, chat_id, "Заказ уже передан в работу.\\nАвтоматическая отмена недоступна.")\n'
        '                else:\n'
        '                    _send_buyer_message(c, chat_id, BUYER_AUTO_CANCEL_UNAVAILABLE_TEXT)\n'
        '                return True\n'
        '            try:\n'
        '                c.account.refund(order_id)\n'
