        '                rt.logger.error(f"BUYER CANCEL REFUND FAILED: order=#{order_id}, error={ex}")\n'
        '                _transition_waiting_state(ctx, order_id, buyer_id, chat_id, BUYER_STATE_LINK_PAUSED, saved_link_marker=None, select_order=False)\n'
        '                _send_admin_order_alert(\n'
        '                    order_id_funpay=order_id,\n'
        '                    reason=f"покупатель запросил !отмена, но автоматический refund не сработал: {ex}",\n'
        '                    bot_action="refund не выполнен, ожидание ссылки приостановлено",\n'
        '                    action="проверьте заказ и при необходимости отмените вручную",\n'
