        '                )\n'
        '                _send_buyer_message(c, chat_id, BUYER_AUTO_CANCEL_FAILED_TEXT)\n'
        '                return True\n'
        '\n'
        '            try:\n'
        '                update_order_fields(\n'
        '                    order_id,\n'
        '                    funpay_status="refunded",\n'
        '                    buyer_flow_state=BUYER_STATE_REFUNDED,\n'
