        '            return True\n'
        '\n'
        '        _transition_waiting_state(ctx, order_id, buyer_id, chat_id, BUYER_STATE_LINK_PAUSED, saved_link_marker=None, select_order=False)\n'
        '        _send_buyer_message(c, chat_id, "Ввод ссылки отменён.\\n\\nЗаказ FunPay не отменён.\\nЕсли хотите отменить заказ, напишите продавцу.\\nЧтобы снова отправить ссылку, напишите: !ссылка")\n'
        '        return True\n'
        '\n'
