        '    service_number = parsed_service_number if (parsed_service_number is not None and parsed_service_number > 0) else 1\n'
        '    result = _fetch_single_order_status(service_number, panel_order_id)\n'
        '    order_id_funpay = str(found.get("order_id") or found.get("order_id_funpay") or "")\n'
        '    if result.get("ok"):\n'
        '        _apply_status_result(c, found, result)\n'
        '        found = get_order_data(order_id_funpay) or found\n'
        '        status_text = _human_panel_status(found)\n'
        '        quantity_text = _format_buyer_progress(found)\n'
        '        c.send_message(\n'
        '            msg_chat_id,\n'
        '            f"📦 {_format_buyer_lot_title(found)}\\n\\nСтатус: {status_text}\\nПрогресс: {quantity_text}\\n\\n"\n'
        '            f"Пожалуйста, не злоупотребляйте командой.\\nМы уведомим вас, когда заказ будет завершён.",\n'
        '        )\n'
        '        return True\n'
        '\n'
        '    if order_id_funpay:\n'
        '        update_order_fields(\n'
        '            order_id_funpay,\n'
        '            status_last_error=result.get("error") or "status_error",\n'
        '            status_last_checked_at=_now_str(),\n'
        '            updated_at=_now_str(),\n'
        '        )\n'
        '    c.send_message(msg_chat_id, "Не удалось проверить статус. Попробуйте позже или напишите продавцу.")\n'
        '    return True\n'
        '\n'
        '\n'
        'def _handle_buyer_refill_command(\n'
        '    c: Cardinal,\n'
        '    msg_text: str,\n'
        '    msg_author_id: Any,\n'
        '    msg_chat_id: int,\n'
        ') -> bool:\n'
        '    match = re.match(r"^рефилл\\s+(.+?)\\s*$", msg_text, re.IGNORECASE)\n'
        '    if not match:\n'
        '        return False\n'
        '\n'
        '    found = _resolve_buyer_command_order(c, match.group(1).strip(), msg_author_id, msg_chat_id)\n'
        '    if not found:\n'
        '        return True\n'
        '    if _apply_refund_gate(c, found, notify_chat_id=msg_chat_id, force_check=True):\n'
        '        return True\n'
        '\n'
        '    panel_order_id = _get_panel_order_id(found)\n'
        '    if panel_order_id is None:\n'
        '        c.send_message(msg_chat_id, "Заказ ещё не запущен. Рефилл будет доступен только после запуска заказа.")\n'
        '        return True\n'
        '\n'
        '    service_number = _safe_int(found.get("service_number"))\n'
        '    if service_number is None:\n'
        '        c.send_message(msg_chat_id, _REFILL_UNAVAILABLE_TEXT)\n'
        '        return True\n'
        '\n'
        '    cfg = load_config()\n'
        '    api_url, api_key, config_err = _extract_service_credentials(cfg, service_number)\n'
        '    if config_err or not api_url or _validate_api_key_for_action(service_number, "refill", api_key):\n'
        '        c.send_message(msg_chat_id, _REFILL_UNAVAILABLE_TEXT)\n'
        '        return True\n'
        '\n'
        '    try:\n'
        '        _rr, rdata, _raw_text, invalid_json = _panel_api_json(\n'
        '            api_url,\n'
        '            {"key": api_key, "action": "refill", "order": panel_order_id},\n'
        '            timeout=15,\n'
        '        )\n'
        '        if invalid_json or not isinstance(rdata, dict):\n'
        '            raise ValueError("панель не вернула JSON рефилла")\n'
        '        refill_id = rdata.get("refill")\n'
        '        status_value = rdata.get("status", 0)\n'
        '        has_error = bool(rdata.get("error")) or isinstance(refill_id, dict)\n'
        '        refill_ok = (not has_error) and (\n'
        '            (refill_id not in (None, "", 0, "0", False))\n'
        '            or str(status_value).lower() in ("1", "true", "success")\n'
        '        )\n'
        '        if refill_ok:\n'
        '            c.send_message(\n'
        '                msg_chat_id,\n'
        '                f"🔄 Рефилл запрошен.\\n\\nID заказа в сервисе: {panel_order_id}\\n\\n"\n'
        '                f"Если услуга поддерживает гарантию, панель обработает запрос автоматически.",\n'
        '            )\n'
        '        else:\n'
        '            c.send_message(msg_chat_id, _REFILL_UNAVAILABLE_TEXT)\n'
        '    except Exception as exc:\n'
        '        safe_err = _sanitize_secret_text(exc, api_key)\n'
        '        logger.warning(f"Ошибка рефилла для заказа panel={panel_order_id}: {safe_err}")\n'
        '        c.send_message(msg_chat_id, "Не удалось запросить рефилл. Попробуйте позже или напишите продавцу.")\n'
        '    return True\n'
        '\n'
        '\n'
        'def _handle_new_message_event(c: Cardinal, e: NewMessageEvent, my_id: Any) -> None:\n'
        '    if e.message.author_id == my_id:\n'
        '        return\n'
        '\n'
        '    msg_text = normalize_incoming_text(e.message.text or "")\n'
        '    msg_author_id = e.message.author_id\n'
        '    msg_chat_id = e.message.chat_id\n'
        '    logger.info(f"Новое сообщение от {e.message.author}: {msg_text}")\n'
        '\n'
        '    if msg_author_id == 0:\n'
        '        _sync_funpay_status_from_event(c, e.message)\n'
        '        return\n'
        '\n'
        '    for handler in (\n'
        '        _handle_buyer_commands_command,\n'
        '        _handle_buyer_smm_command,\n'
        '        _handle_buyer_link_command,\n'
        '        _handle_buyer_cancel_command,\n'
        '        _handle_buyer_check_command,\n'
        '        _handle_buyer_refill_command,\n'
        '        _handle_buyer_flow_message,\n'
        '    ):\n'
        '        if handler(c, msg_text, msg_author_id, msg_chat_id):\n'
        '            return\n'
        '\n'
        '\n'
        'def _handle_unmatched_order(\n'
        '    c: Cardinal,\n'
        '    order_id: Any,\n'
        '    order_desc: str,\n'
        '    order_price: Any,\n'
        '    order_amount: Any,\n'
        '    buyer_chat_id: int,\n'
        '    buyer_id: Any,\n'
        '    buyer_username: Any,\n'
        '    lot_result: dict,\n'
        ') -> None:\n'
        '    if _is_lot_match_no_match(lot_result):\n'
        '        logger.info(\n'
        '            "AUTO SMM SKIP NON-AUTOSMM ORDER: order=%s, description=%r",\n'
        '            order_id,\n'
        '            str(order_desc or "")[:300],\n'
        '        )\n'
        '        return\n'
        '\n'
        '    error_code = str(lot_result.get("error") or "no_match")\n'
        '    stop_reason = "lot_match_ambiguous" if _is_lot_match_ambiguous(lot_result) else "lot_match_failed"\n'
        '    if get_order_data(str(order_id)) is not None:\n'
        '        logger.info("DUPLICATE UNMATCHED NEW_ORDER SKIPPED: order=%s", order_id)\n'
        '        return\n'
        '    logger.warning("LOT MATCH MANUAL CHECK: order=%s, error=%s", order_id, error_code)\n'
        '    created = _upsert_buyer_flow_order_record(\n'
        '        chat_id=buyer_chat_id,\n'
        '        buyer_id=buyer_id,\n'
        '        buyer_username=buyer_username,\n'
        '        order_id_funpay=str(order_id),\n'
        '        lot_title=str(order_desc or "SMM-заказ"),\n'
        '        order_price=order_price,\n'
        '        order_amount=order_amount,\n'
        '        service_id=0,\n'
        '        real_amount=0,\n'
        '        service_number=0,\n'
        '        funpay_status="open",\n'
        '        state=BUYER_STATE_FAILED,\n'
        '        saved_link=None,\n'
        '    )\n'
        '    if created is False:\n'
        '        logger.info("DUPLICATE UNMATCHED NEW_ORDER SKIPPED ON UPSERT: order=%s", order_id)\n'
        '        return\n'
        '    update_order_fields(\n'
        '        str(order_id),\n'
        '        status="unknown",\n'
        '        buyer_flow_state=BUYER_STATE_FAILED,\n'
        '        status_stop_reason=stop_reason,\n'
        '        updated_at=_now_str(),\n'
        '    )\n'
        '    _send_lot_match_manual_alert(order_id, order_desc, lot_result)\n'
        '    if _normalize_chat_id(buyer_chat_id) is not None:\n'
        '        _send_buyer_message(c, buyer_chat_id, BUYER_LOT_MATCH_MANUAL_TEXT)\n'
        '    else:\n'
        '        logger.warning("UNMATCHED ORDER BUYER MESSAGE SKIPPED: missing buyer_chat_id for order=#%s", order_id)\n'
        '\n'
        '\n'
        'def _persist_and_notify_matched_order(\n'
        '    c: Cardinal,\n'
        '    cfg: Dict[str, Any],\n'
        '    order_: Any,\n'
        '    buyer_chat_id: int,\n'
        '    buyer_id: Any,\n'
        '    buyer_username: str,\n'
        '    lot_result: Dict[str, Any],\n'
        ') -> None:\n'
        '    order_id = order_.id\n'
        '    existing_order = get_order_data(str(order_id))\n'
        '    if existing_order is not None:\n'
        '        logger.info(\n'
        '            "DUPLICATE NEW_ORDER EVENT SKIPPED: order=#%s already exists (state=%s, funpay_status=%s)",\n'
        '            order_id,\n'
        '            existing_order.get("buyer_flow_state"),\n'
        '            existing_order.get("funpay_status"),\n'
        '        )\n'
        '        return\n'
        '    order_desc = order_.description\n'
        '    order_amount = order_.amount\n'
        '    order_price = order_.price\n'
        '    service_id = lot_result.get("service_id")\n'
        '    real_amount = lot_result.get("real_amount")\n'
        '    srv_number = lot_result.get("service_number", 1)\n'
        '    matched_lot_key = lot_result.get("lot_key")\n'
        '    matched_lot_title = lot_result.get("lot_title") or order_desc\n'
        '\n'
        '    created = _upsert_buyer_flow_order_record(\n'
        '        chat_id=buyer_chat_id,\n'
        '        buyer_id=buyer_id,\n'
        '        buyer_username=buyer_username,\n'
        '        order_id_funpay=str(order_id),\n'
        '        lot_title=matched_lot_title,\n'
        '        order_price=order_price,\n'
        '        order_amount=order_amount,\n'
        '        service_id=service_id,\n'
        '        real_amount=real_amount,\n'
        '        service_number=srv_number,\n'
        '        lot_key=matched_lot_key,\n'
        '        funpay_status="open",\n'
        '        state=BUYER_STATE_WAITING_LINK,\n'
        '    )\n'
        '    if created is False:\n'
        '        logger.info("DUPLICATE NEW_ORDER EVENT SKIPPED ON UPSERT: order=#%s", order_id)\n'
        '        return\n'
        '\n'
        '    now_ts = time.time()\n'
        '    with rt.CONTEXT_LOCK:\n'
        '        rt.waiting_for_link[str(order_id)] = {\n'
        '            "buyer_id": buyer_id,\n'
        '            "chat_id": buyer_chat_id,\n'
        '            "buyer_username": buyer_username,\n'
        '            "service_id": service_id,\n'
        '            "real_amount": real_amount,\n'
        '            "order_id_funpay": str(order_id),\n'
        '            "price": order_price,\n'
        '            "service_number": srv_number,\n'
        '            "lot_key": matched_lot_key,\n'
        '            "lot_title": matched_lot_title,\n'
        '            "state": BUYER_STATE_WAITING_LINK,\n'
        '            "step": "await_link",\n'
        '            "created_ts": now_ts,\n'
        '            "updated_ts": now_ts,\n'
        '        }\n'
        '\n'
        '    order_record = get_order_data(str(order_id)) or {}\n'
        '    msg_payment = _render_template(\n'
        '        cfg.get("messages", {}).get("after_payment", "❤️ Спасибо за оплату! Укажите ссылку для запуска заказа."),\n'
        '        order_record,\n'
        '        {\n'
        '            "buyer_username": buyer_username,\n'
        '            "lot_title": matched_lot_title,\n'
        '            "orderDesc": matched_lot_title,\n'
        '            "order_id_funpay": order_id,\n'
        '            "order_price": order_price,\n'
        '            "orderPrice": order_price,\n'
        '            "order_amount": order_amount,\n'
        '            "orderAmount": order_amount,\n'
        '            "currency": "RUB",\n'
        '            "total_quantity": real_amount,\n'
        '            "done_quantity": 0,\n'
        '            "left_quantity": real_amount,\n'
        '            "progress_percent": 0,\n'
        '            "funpay_status": "open",\n'
        '            "panel_status": "",\n'
        '        },\n'
        '    )\n'
        '    if _normalize_chat_id(buyer_chat_id) is None:\n'
        '        logger.warning("BUYER PROMPT SKIPPED: missing buyer_chat_id for order=#%s", order_id)\n'
        '        return\n'
        '    try:\n'
        '        _send_buyer_message(c, buyer_chat_id, msg_payment)\n'
        '    except Exception as exc:\n'
        '        logger.warning("Не удалось отправить приветствие покупателю по заказу #%s: %s", order_id, exc)\n'
        '\n'
        '\n'
        'def _resolve_buyer_chat_target(c: Cardinal, order_: Any) -> tuple[Any, Any, str]:\n'
        '    """Resolve buyer numeric chat_id via Cardinal cache first, falling back to get_order only on miss."""\n'
        '    order_id = getattr(order_, "id", None)\n'
        '    buyer_id = getattr(order_, "buyer_id", None)\n'
        '    buyer_username = str(getattr(order_, "buyer_username", None) or "")\n'
        '    raw_chat_id = getattr(order_, "chat_id", None)\n'
        '    buyer_chat_id: Any = raw_chat_id if isinstance(raw_chat_id, int) else None\n'
        '\n'
        '    account = getattr(c, "account", None)\n'
        '    if buyer_chat_id is None and buyer_username and account is not None:\n'
        '        get_chat_by_name = getattr(account, "get_chat_by_name", None)\n'
        '        if callable(get_chat_by_name):\n'
        '            try:\n'
        '                chat_shortcut = get_chat_by_name(buyer_username)\n'
        '                cached_chat_id = getattr(chat_shortcut, "id", None)\n'
        '                if isinstance(cached_chat_id, int):\n'
        '                    buyer_chat_id = cached_chat_id\n'
        '            except Exception as exc:\n'
        '                logger.debug(f"get_chat_by_name({buyer_username}) cache lookup failed: {exc}")\n'
        '\n'
        '    if (buyer_chat_id is None or buyer_id is None) and account is not None and callable(getattr(account, "get_order", None)):\n'
        '        try:\n'
        '            od_full = account.get_order(order_id)\n'
        '            full_chat_id = getattr(od_full, "chat_id", None)\n'
        '            if full_chat_id is not None:\n'
        '                buyer_chat_id = full_chat_id\n'
        '            if buyer_id is None:\n'
        '                buyer_id = getattr(od_full, "buyer_id", None)\n'
        '            if not buyer_username:\n'
        '                buyer_username = str(getattr(od_full, "buyer_username", None) or "")\n'
        '        except Exception as exc:\n'
        '            logger.warning(f"Не удалось получить детали заказа #{order_id} через get_order: {exc}")\n'
        '\n'
        '    if buyer_chat_id is None:\n'
        '        buyer_chat_id = raw_chat_id\n'
        '    return buyer_chat_id, buyer_id, buyer_username\n'
        '\n'
        '\n'
        'def _handle_new_order_event(c: Cardinal, e: NewOrderEvent) -> None:\n'
        '    order_ = e.order\n'
        '    order_id = order_.id\n'
        '    order_desc = order_.description\n'
        '    order_amount = order_.amount\n'
        '    order_price = order_.price\n'
        '    logger.info(f"Новый заказ #{order_id}: {order_desc}, x{order_amount}")\n'
        '\n'
        '    # Match the lot before any FunPay API calls so non-AutoSMM orders trigger zero HTTP requests.\n'
        '    lot_result = resolve_lot_by_description(order_desc, order_amount)\n'
        '    if not lot_result.get("ok"):\n'
        '        if _is_lot_match_no_match(lot_result):\n'
        '            logger.info(\n'
        '                "AUTO SMM SKIP NON-AUTOSMM ORDER: order=%s, description=%r",\n'
        '                order_id,\n'
        '                str(order_desc or "")[:300],\n'
        '            )\n'
        '            return\n'
        '        buyer_chat_id, buyer_id, buyer_username = _resolve_buyer_chat_target(c, order_)\n'
        '        with rt.get_order_lock(order_id):\n'
        '            _handle_unmatched_order(\n'
        '                c,\n'
        '                order_id,\n'
        '                order_desc,\n'
        '                order_price,\n'
        '                order_amount,\n'
        '                buyer_chat_id,\n'
        '                buyer_id,\n'
        '                buyer_username,\n'
        '                lot_result,\n'
        '            )\n'
        '        return\n'
        '\n'
        '    cfg = load_config()\n'
        '    buyer_chat_id, buyer_id, buyer_username = _resolve_buyer_chat_target(c, order_)\n'
        '    with rt.get_order_lock(order_id):\n'
        '        _persist_and_notify_matched_order(\n'
        '            c,\n'
        '            cfg,\n'
        '            order_,\n'
        '            buyer_chat_id,\n'
        '            buyer_id,\n'
        '            buyer_username,\n'
        '            lot_result,\n'
        '        )\n'
        '\n'
        '\n'
        '_EVENT_WORKER_COUNT = 4\n'
        '_EVENT_SHARD_QUEUE_MAXSIZE = 512\n'
        '_STOP_SENTINEL = object()\n'
        '_EVENT_WORKERS_LOCK = threading.RLock()\n'
        '_SHARD_QUEUES: List[queue.Queue] = []\n'
        '_EVENT_WORKERS: List[threading.Thread] = []\n'
        '\n'
        '\n'
        'def _is_supported_event(e: Any) -> bool:\n'
        '    if isinstance(e, (NewMessageEvent, NewOrderEvent)):\n'
        '        return True\n'
        '    return OrderStatusChangedEvent is not None and isinstance(e, OrderStatusChangedEvent)\n'
        '\n'
        '\n'
        'def _resolve_event_shard_key(e: Any) -> str:\n'
        '    if isinstance(e, NewMessageEvent):\n'
        '        msg = getattr(e, "message", None)\n'
        '        author = str(getattr(msg, "author", "") or "").strip().lower()\n'
        '        author_id = getattr(msg, "author_id", None)\n'
        '        if author and author_id != 0 and author != "funpay":\n'
        '            return f"user:{author}"\n'
        '        chat_id = getattr(msg, "chat_id", None)\n'
        '        if chat_id is not None:\n'
        '            return f"chat:{chat_id}"\n'
        '        return "default"\n'
        '    if isinstance(e, NewOrderEvent):\n'
        '        order_obj = getattr(e, "order", None)\n'
        '        buyer_username = str(getattr(order_obj, "buyer_username", "") or getattr(order_obj, "buyer_name", "") or "").strip().lower()\n'
        '        if buyer_username:\n'
        '            return f"user:{buyer_username}"\n'
        '        raw_chat_id = getattr(order_obj, "chat_id", None)\n'
        '        if isinstance(raw_chat_id, int):\n'
        '            return f"chat:{raw_chat_id}"\n'
        '        order_id = str(getattr(order_obj, "id", "") or "").strip().lstrip("#")\n'
        '        return f"order:{order_id}" if order_id else "default"\n'
        '    if OrderStatusChangedEvent is not None and isinstance(e, OrderStatusChangedEvent):\n'
        '        order_obj = getattr(e, "order", None)\n'
        '        buyer_username = str(getattr(order_obj, "buyer_username", "") or getattr(order_obj, "buyer_name", "") or "").strip().lower()\n'
        '        if buyer_username:\n'
        '            return f"user:{buyer_username}"\n'
        '        order_id = str(getattr(order_obj, "id", "") or "").strip().lstrip("#")\n'
        '        return f"order:{order_id}" if order_id else "default"\n'
        '    return "default"\n'
        '\n'
        '\n'
        'def _dispatch_event_sync(c: Cardinal, e: Any) -> None:\n'
        '    if isinstance(e, NewMessageEvent):\n'
        '        my_id = getattr(getattr(c, "account", None), "id", None)\n'
        '        _handle_new_message_event(c, e, my_id)\n'
        '    elif isinstance(e, NewOrderEvent):\n'
        '        _handle_new_order_event(c, e)\n'
        '    elif OrderStatusChangedEvent is not None and isinstance(e, OrderStatusChangedEvent):\n'
        '        _sync_funpay_status_from_order_event(c, e)\n'
        '\n'
        '\n'
        'def _shard_worker_loop(shard_queue: queue.Queue) -> None:\n'
        '    while True:\n'
        '        item = shard_queue.get()\n'
        '        try:\n'
        '            if item is _STOP_SENTINEL:\n'
        '                return\n'
        '            c, e = item\n'
        '            _dispatch_event_sync(c, e)\n'
        '        except Exception as exc:\n'
        '            logger.exception(f"Unhandled exception in AutoSMM event worker: {exc}")\n'
        '        finally:\n'
        '            shard_queue.task_done()\n'
        '\n'
        '\n'
        'def _ensure_event_workers_locked() -> None:\n'
        '    if len(_SHARD_QUEUES) == _EVENT_WORKER_COUNT and len(_EVENT_WORKERS) == _EVENT_WORKER_COUNT:\n'
        '        if all(worker.is_alive() for worker in _EVENT_WORKERS):\n'
        '            return\n'
        '    if not _SHARD_QUEUES or len(_SHARD_QUEUES) != _EVENT_WORKER_COUNT:\n'
        '        _SHARD_QUEUES[:] = [queue.Queue(maxsize=_EVENT_SHARD_QUEUE_MAXSIZE) for _ in range(_EVENT_WORKER_COUNT)]\n'
        '    rebuilt_workers: List[threading.Thread] = []\n'
        '    for idx in range(_EVENT_WORKER_COUNT):\n'
        '        existing = _EVENT_WORKERS[idx] if idx < len(_EVENT_WORKERS) else None\n'
        '        if existing is not None and existing.is_alive():\n'
        '            rebuilt_workers.append(existing)\n'
        '            continue\n'
        '        worker = threading.Thread(\n'
        '            target=_shard_worker_loop,\n'
        '            args=(_SHARD_QUEUES[idx],),\n'
        '            name=f"autosmm-event-worker-{idx}",\n'
        '            daemon=True,\n'
        '        )\n'
        '        worker.start()\n'
        '        rebuilt_workers.append(worker)\n'
        '    _EVENT_WORKERS[:] = rebuilt_workers\n'
        '\n'
        '\n'
        'def start_event_workers() -> None:\n'
        '    """Start or verify sharded background worker threads for FunPay event dispatch."""\n'
        '    with _EVENT_WORKERS_LOCK:\n'
        '        _ensure_event_workers_locked()\n'
        '\n'
        '\n'
        'def flush_event_queue(timeout: float = 5.0) -> bool:\n'
        '    """Wait up to `timeout` seconds for all currently queued FunPay events to complete."""\n'
        '    with _EVENT_WORKERS_LOCK:\n'
        '        queues = list(_SHARD_QUEUES)\n'
        '    deadline = time.monotonic() + max(0.0, float(timeout))\n'
        '    for shard_queue in queues:\n'
        '        with shard_queue.all_tasks_done:\n'
        '            while shard_queue.unfinished_tasks > 0:\n'
        '                remaining = deadline - time.monotonic()\n'
        '                if remaining <= 0:\n'
        '                    return False\n'
        '                shard_queue.all_tasks_done.wait(timeout=remaining)\n'
        '    return True\n'
        '\n'
        '\n'
        'def stop_event_workers(*, drain: bool = True, timeout: float = 5.0) -> None:\n'
        '    """Stop all sharded FunPay event workers cleanly and wait up to `timeout` seconds for exit."""\n'
        '    with _EVENT_WORKERS_LOCK:\n'
        '        queues = list(_SHARD_QUEUES)\n'
        '        workers = list(_EVENT_WORKERS)\n'
        '        _SHARD_QUEUES.clear()\n'
        '        _EVENT_WORKERS.clear()\n'
        '\n'
        '    if not drain:\n'
        '        for shard_queue in queues:\n'
        '            while True:\n'
        '                try:\n'
        '                    shard_queue.get_nowait()\n'
        '                    shard_queue.task_done()\n'
        '                except queue.Empty:\n'
        '                    break\n'
        '\n'
        '    for shard_queue in queues:\n'
        '        while True:\n'
        '            try:\n'
        '                shard_queue.put_nowait(_STOP_SENTINEL)\n'
        '                break\n'
        '            except queue.Full:\n'
        '                try:\n'
        '                    shard_queue.get_nowait()\n'
        '                    shard_queue.task_done()\n'
        '                except queue.Empty:\n'
        '                    continue\n'
        '\n'
        '    deadline = time.monotonic() + max(0.0, float(timeout))\n'
        '    current = threading.current_thread()\n'
        '    for worker in workers:\n'
        '        is_alive_fn = getattr(worker, "is_alive", None)\n'
        '        if worker is current or (callable(is_alive_fn) and not is_alive_fn()):\n'
        '            continue\n'
        '        remaining = deadline - time.monotonic()\n'
        '        if remaining <= 0:\n'
        '            break\n'
        '        join_fn = getattr(worker, "join", None)\n'
        '        if callable(join_fn):\n'
        '            join_fn(timeout=max(0.05, remaining))\n'
        '\n'
        '\n'
        'def auto_smm_handler(c: Cardinal, e: Any, *args: Any) -> None:\n'
        '    """Enqueue FunPay NewMessageEvent, NewOrderEvent, and OrderStatusChangedEvent without blocking Runner."""\n'
