        '\n'
        '\n'
        'def _parse_dt_or_none(value: Any) -> Optional[datetime]:\n'
        '    raw_value = str(value or "").strip()\n'
        '    if not raw_value:\n'
        '        return None\n'
        '    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M:%S.%f"):\n'
        '        try:\n'
        '            return datetime.strptime(raw_value, fmt)\n'
