        '\n'
        '\n'
        'def _map_cardinal_order_status_to_funpay_status(order_status: Any) -> Optional[str]:\n'
        '    order_statuses = getattr(enums, "OrderStatuses", None)\n'
        '    if order_statuses is not None:\n'
        '        status_mapping = {\n'
        '            getattr(order_statuses, "PAID", None): "open",\n'
        '            getattr(order_statuses, "CLOSED", None): "closed",\n'
        '            getattr(order_statuses, "REFUNDED", None): "refunded",\n'
        '            getattr(order_statuses, "PARTIALLY_REFUNDED", None): "partially_refunded",\n'
        '        }\n'
        '        for candidate, normalized in status_mapping.items():\n'
        '            if candidate is not None and order_status == candidate:\n'
        '                return normalized\n'
        '\n'
        '    raw_status = str(order_status or "").strip().lower().replace("-", "_").replace(" ", "_")\n'
        '    if raw_status.endswith(".paid") or raw_status == "paid":\n'
        '        return "open"\n'
        '    if raw_status.endswith(".closed") or raw_status == "closed":\n'
        '        return "closed"\n'
        '    if raw_status.endswith(".refunded") or raw_status == "refunded":\n'
        '        return "refunded"\n'
        '    if "partially_refunded" in raw_status:\n'
        '        return "partially_refunded"\n'
        '    return None\n'
        '\n'
        '\n'
        'def _parse_fetched_order_status(order_data: Any, order_id_funpay: str) -> Dict[str, Any]:\n'
        '    if order_data is None:\n'
        '        return {\n'
        '            "ok": False,\n'
        '            "error": "order_not_found",\n'
        '            "detail": f"Заказ #{order_id_funpay} не найден в ответе FunPay",\n'
