        '\n'
        'def _links_is_valid_buyer_target(target: str, *, allowed_domains) -> Tuple[bool, str]:\n'
        "    target = str(target or '').strip()\n"
        '    if not target:\n'
        "        return (False, '❌ Укажите ссылку или юзернейм.')\n"
        "    if target.lower().startswith('https://'):\n"
        "        return _links_is_valid_link('https://' + target[8:], allowed_domains=allowed_domains)\n"
        "    if target.startswith('@'):\n"
        '        uname = target[1:].strip()\n'
        "        if not re.fullmatch('[A-Za-z0-9_.-]{2,64}', uname):\n"
        "            return (False, '❌ Некорректный формат юзернейма. Разрешены латинские буквы, цифры и символы _ . -')\n"
        "        return (True, '✅ Юзернейм корректен.')\n"
        "    if re.fullmatch('[A-Za-z0-9_.-]{3,64}', target):\n"
        '        if _is_domain_like_bare_token(target):\n'
        '            return (False, INVALID_LINK_SCHEME_TEXT)\n'
        "        return (True, '✅ Юзернейм корректен.')\n"
        "    return (False, '❌ Ссылка или юзернейм не приняты. Отправьте ссылку (https://...) или юзернейм (@channel).')\n"
        '\n'
        '\n'
        'def _default_allowed_domains() -> List[str]:\n'
        '    """Load persisted allowed domains from storage."""\n'
        '    return load_valid_links()\n'
        '\n'
        '\n'
