        '\n'
        'STATUS_BATCH_SIZE = 50\n'
        'STATUS_BATCH_INTERVAL_SECONDS = 300\n'
        'INCORRECT_ORDER_ID_MAX_ATTEMPTS = 3\n'
        '\n'
        '_SOFT_STATUS_ERRORS = (\n'
