        '    def has_any(tokens: List[str]) -> bool:\n'
        '        for token in tokens:\n'
        '            token_norm = str(token or "").lower().replace("-", "_")\n'
        '            if token_norm in haystack or token_norm.replace("_", " ") in haystack_spaces:\n'
        '                return True\n'
        '        return False\n'
        '\n'
        '    if has_any([\n'
