        '            "response": payload if payload is not None else raw_text,\n'
        '            "http_status": http_status,\n'
        '        }\n'
        '\n'
        '    if action in ("status", "refill") and payload is not None and not (isinstance(payload, dict) and payload.get("error")):\n'
        '        return {\n'
        '            "error": "success",\n'
