        '        f"Ссылка: https://funpay.com/orders/{order_id_funpay}/"\n'
        '    )\n'
        '\n'
        '    return send_tg_notification(notification_chat_id, alert_text)\n'
        '\n'
        '\n'
        'def _send_manual_check_alert_once(\n'
        '    order_record: Dict,\n'
        '    reason: str = "не удалось подтвердить состояние заказа",\n'
        ') -> None:\n'
        '    """Emit at most one manual-check alert per order record."""\n'
        '    if not order_record or order_record.get("manual_check_alert_sent", False):\n'
        '        return\n'
        '\n'
        '    cfg = load_config()\n'
        '    if not cfg.get("notification_chat_id") or rt.bot is None:\n'
        '        return\n'
        '\n'
        '    order_id_funpay = str(order_record.get("order_id") or "").strip()\n'
        '    if not order_id_funpay:\n'
        '        return\n'
        '\n'
        '    claimed, snapshot = db_orders.claim_manual_check_alert(order_id_funpay)\n'
        '    if not claimed:\n'
        '        if snapshot is not None:\n'
        '            order_record["manual_check_alert_sent"] = bool(snapshot.get("manual_check_alert_sent", True))\n'
