        '\n'
        '\n'
        'def _format_alert_money(value: Any) -> str:\n'
        '    """Format monetary values cleanly without trailing \'.00\' noise."""\n'
        '    try:\n'
        '        num = float(value)\n'
        '    except (ValueError, TypeError):\n'
        '        return str(value)\n'
        '    if num.is_integer():\n'
        '        return str(int(num))\n'
        '    return f"{num:.2f}".rstrip("0").rstrip(".")\n'
        '\n'
        '\n'
        'def _fetch_start_notification_charge(\n'
        '    order_id_funpay: str,\n'
        '    panel_order_id: int,\n'
        '    api_url: str,\n'
        '    api_key: str,\n'
        '    lot_price: float,\n'
        '    service_number: Optional[int],\n'
        ') -> Tuple[Optional[float], Optional[str], Optional[float], Optional[float], Optional[float]]:\n'
        '    """Query the panel status once after order start to persist charge and RUB profit."""\n'
        '    if service_number is None:\n'
        '        return None, None, None, None, None\n'
        '    try:\n'
        '        invalid_key_payload = _validate_api_key_for_action(service_number, "status", api_key)\n'
        '        if invalid_key_payload:\n'
        '            rt.logger.warning(\n'
        '                f"{rt.LOGGER_PREFIX} Пропускаю action=status для уведомления о старте заказа "\n'
        '                f"#{order_id_funpay}: {invalid_key_payload[\'detail\']}"\n'
        '            )\n'
        '            return None, None, None, None, None\n'
        '\n'
        '        _status_resp, status_data, _raw_text, invalid_json = _panel_api_json(\n'
        '            api_url,\n'
        '            {"key": api_key, "action": "status", "order": panel_order_id},\n'
        '            timeout=10,\n'
        '        )\n'
        '        if invalid_json or not isinstance(status_data, dict):\n'
        '            raise ValueError("панель не вернула JSON статуса")\n'
        '        if status_data.get("error") or status_data.get("charge") in (None, ""):\n'
        '            rt.logger.warning(\n'
        '                f"START NOTIFICATION CHARGE UNAVAILABLE: order=#{order_id_funpay}, "\n'
        '                f"panel_order_id={panel_order_id}, error={status_data.get(\'error\')}"\n'
        '            )\n'
        '            return None, None, None, None, None\n'
        '\n'
        '        charge = safe_float(status_data.get("charge"), 0.0)\n'
        '        raw_currency = status_data.get("currency")\n'
        '        if raw_currency not in (None, ""):\n'
        '            currency = normalize_currency_code(raw_currency)\n'
        '        else:\n'
        '            from ..core.panel_balances import get_cached_service_balance\n'
