        '            if panel_currency not in (None, ""):\n'
        '                currency = normalize_currency_code(panel_currency)\n'
        '            else:\n'
        '                stored_order = get_order_data(order_id_funpay) or {}\n'
        '                currency = normalize_currency_code(stored_order.get("currency") or "RUB")\n'
        '        fx_info = compute_order_profit_rub(lot_price, charge, currency)\n'
        '        try:\n'
        '            update_order_charge_and_net(\n'
        '                order_id_funpay,\n'
        '                fx_info["spent"],\n'
        '                currency=fx_info["currency"],\n'
        '                net_profit=fx_info["net_profit"],\n'
        '                spent_rub=fx_info["spent_rub"],\n'
        '                fx_rate_to_rub=fx_info["fx_rate_to_rub"],\n'
        '            )\n'
        '        except (sqlite3.Error, OSError, ValueError, TypeError):\n'
        '            rt.logger.exception(f"Не удалось сохранить charge/chistota для заказа #{order_id_funpay}")\n'
        '        return (\n'
        '            fx_info["spent"],\n'
        '            fx_info["currency"],\n'
        '            fx_info["spent_rub"],\n'
        '            fx_info["fx_rate_to_rub"],\n'
        '            fx_info["net_profit"],\n'
        '        )\n'
        '    except (requests.RequestException, ValueError, TypeError, KeyError) as exc:\n'
        '        rt.logger.error(\n'
        '            f"Ошибка при получении данных action=status для уведомления о начале заказа #{order_id_funpay}: "\n'
        '            f"{_sanitize_secret_text(exc, api_key)}"\n'
        '        )\n'
        '        return None, None, None, None, None\n'
        '\n'
        '\n'
        'def _format_order_started_text(\n'
        '    *,\n'
        '    title: str,\n'
        '    info_title: Optional[str],\n'
        '    order_id_funpay: str,\n'
        '    buyer_username: str,\n'
        '    reason: Optional[str],\n'
        '    action_text: Optional[str],\n'
        '    lot_price: float,\n'
        '    charge: Optional[float],\n'
        '    currency: str,\n'
        '    real_amount: int,\n'
        '    order_url: str,\n'
        '    spent_rub: Optional[float] = None,\n'
        '    net_profit: Optional[float] = None,\n'
        ') -> str:\n'
        '    norm_cur = normalize_currency_code(currency)\n'
        '    resolved_spent_rub = spent_rub if charge is not None else None\n'
        '    if charge is not None and resolved_spent_rub is None:\n'
        '        if norm_cur == "RUB":\n'
        '            resolved_spent_rub = round(float(charge or 0.0), 4)\n'
        '        else:\n'
        '            resolved_spent_rub, _rate = convert_to_rub(charge, norm_cur, allow_network=False)\n'
        '\n'
        '    computed_profit = (\n'
        '        net_profit\n'
        '        if net_profit is not None\n'
        '        else (round(float(lot_price) - resolved_spent_rub, 2) if resolved_spent_rub is not None else None)\n'
        '    )\n'
        '\n'
        '    parts = [title, ""]\n'
        '    if info_title:\n'
        '        parts.extend([info_title, ""])\n'
        '    parts.extend([f"Заказ: #{order_id_funpay}", f"Покупатель: {buyer_username}", ""])\n'
        '    if reason:\n'
        '        parts.append(f"Причина: {reason}")\n'
        '    if action_text:\n'
        '        parts.append(f"Действие: {action_text}")\n'
        '    if reason or action_text:\n'
        '        parts.append("")\n'
        '    parts.append(f"💰 FunPay: {_format_alert_money(lot_price)} ₽")\n'
        '    if charge is None:\n'
        '        parts.append("💸 Сайт: стоимость уточняется")\n'
        '    elif norm_cur == "RUB" or resolved_spent_rub is None:\n'
        '        parts.append(f"💸 Сайт: {_format_alert_money(charge)} {norm_cur}")\n'
        '    else:\n'
        '        parts.append(f"💸 Сайт: {_format_alert_money(charge)} {norm_cur} (~{_format_alert_money(resolved_spent_rub)} ₽)")\n'
        '\n'
        '    if computed_profit is not None:\n'
        '        parts.append(f"📈 Профит: {_format_alert_money(computed_profit)} ₽")\n'
        '    elif charge is None:\n'
        '        parts.append("📈 Профит: уточняется")\n'
        '    else:\n'
        '        parts.append(f"📈 Профит: недоступен (валюта панели: {norm_cur})")\n'
        '    parts.extend(["", f"📦 Итоговое количество: {real_amount}", f"🔗 {order_url}"])\n'
        '    return "\\n".join(parts)\n'
        '\n'
        '\n'
        'def send_order_started_notification(\n'
        '    c: "Cardinal",\n'
        '    order_id_funpay: str,\n'
        '    panel_order_id: int,\n'
        '    api_url: str,\n'
        '    api_key: str,\n'
        '    lot_price: float,\n'
        '    real_amount: int,\n'
        '    service_number: Optional[int] = None,\n'
        '    title: str = "🚀 AUTOSMM | Старт заказа",\n'
        '    info_title: Optional[str] = None,\n'
        '    reason: Optional[str] = None,\n'
        '    action_text: Optional[str] = None,\n'
        ') -> None:\n'
        '    """Send an order-start notification with charge and profit breakdown to admin chat."""\n'
        '    cfg = load_config()\n'
        '    notification_chat_id = cfg.get("notification_chat_id")\n'
        '    if not notification_chat_id:\n'
