        '            order_id_funpay,\n'
        '            panel_order_id,\n'
        '            api_url,\n'
        '            api_key,\n'
        '            lot_price,\n'
        '            service_number,\n'
        '        )\n'
        '    except Exception as fetch_ex:\n'
        '        rt.logger.warning(\n'
        '            f"Не удалось получить стоимость старта заказа #{order_id_funpay}: {fetch_ex}"\n'
        '        )\n'
        '        charge, currency, spent_rub, _fx_rate, net_profit = None, None, None, None, None\n'
        '\n'
        '    try:\n'
        '        stored_order = get_order_data(order_id_funpay) or {}\n'
        '        stored_spent = stored_order.get("spent")\n'
        '        if charge is not None:\n'
        '            resolved_charge: Optional[float] = charge\n'
        '        elif stored_spent not in (None, "") and safe_float(stored_spent, 0.0) > 0:\n'
        '            resolved_charge = safe_float(stored_spent, 0.0)\n'
        '        else:\n'
        '            resolved_charge = None\n'
        '        resolved_currency = normalize_currency_code(currency or stored_order.get("currency", "RUB"))\n'
        '        resolved_spent_rub = spent_rub if spent_rub is not None else (stored_order.get("spent_rub") if resolved_charge is not None else None)\n'
        '\n'
        '        buyer_username = str(stored_order.get("buyer_username") or "").strip()\n'
        '        if not buyer_username:\n'
        '            try:\n'
        '                order_data = c.account.get_order(order_id_funpay)\n'
        '                buyer_username = getattr(order_data, "buyer_username", None) or "—"\n'
        '            except Exception as exc:\n'
        '                rt.logger.warning(f"Не удалось получить buyer_username для заказа #{order_id_funpay}: {exc}")\n'
        '                buyer_username = "—"\n'
        '\n'
        '        order_url = f"https://funpay.com/orders/{order_id_funpay}/"\n'
        '        notification_text = _format_order_started_text(\n'
        '            title=title,\n'
        '            info_title=info_title,\n'
        '            order_id_funpay=order_id_funpay,\n'
        '            buyer_username=buyer_username,\n'
        '            reason=reason,\n'
        '            action_text=action_text,\n'
        '            lot_price=lot_price,\n'
        '            charge=resolved_charge,\n'
        '            currency=resolved_currency,\n'
        '            real_amount=real_amount,\n'
        '            order_url=order_url,\n'
        '            spent_rub=resolved_spent_rub,\n'
        '            net_profit=net_profit,\n'
        '        )\n'
        '        send_tg_notification(\n'
        '            notification_chat_id,\n'
        '            notification_text,\n'
        '            reply_markup=_build_order_url_markup(order_url),\n'
        '            cardinal=c,\n'
        '        )\n'
        '    except Exception as exc:\n'
        '        rt.logger.error(f"Ошибка при отправке уведомления о начале заказа: {exc}")\n'
        '\n'
        '\n'
        'def _send_completion_notification_if_needed(c: "Cardinal", order_record: Dict) -> None:\n'
        '    """Notify buyer in FunPay chat once a completed order awaits confirmation."""\n'
        '    if not order_record:\n'
        '        return\n'
        '    if str(order_record.get("status", "") or "").lower() != "completed":\n'
        '        return\n'
        '    if bool(order_record.get("completed_notification_sent", False)):\n'
        '        return\n'
        '    order_id_funpay = str(order_record.get("order_id") or "").strip()\n'
        '    if not order_id_funpay:\n'
        '        return\n'
        '\n'
        '    claimed, latest_snapshot = db_orders.claim_completion_notification(order_id_funpay)\n'
        '    if not claimed:\n'
        '        if latest_snapshot is not None:\n'
        '            order_record["completed_notification_sent"] = bool(\n'
        '                latest_snapshot.get("completed_notification_sent", False)\n'
        '            )\n'
        '            rt.logger.info(\n'
        '                f"Completion-уведомление пропущено для заказа #{order_id_funpay}: "\n'
        '                f"funpay_status={get_effective_funpay_status(latest_snapshot)}, "\n'
        '                f"sent={order_record[\'completed_notification_sent\']}"\n'
        '            )\n'
        '        return\n'
        '\n'
        '    active_record = latest_snapshot or order_record\n'
        '    buyer_chat_id = active_record.get("chat_id")\n'
        '    if buyer_chat_id in (None, ""):\n'
        '        update_order_fields(order_id_funpay, completed_notification_sent=False)\n'
        '        return\n'
        '    panel_order_id = active_record.get("id_zakaz")\n'
        '    cfg = load_config()\n'
        '    template_text = (cfg.get("messages") or {}).get("after_completed") or DEFAULT_AFTER_COMPLETED_TEMPLATE\n'
        '    message = _render_template(\n'
        '        template_text,\n'
        '        active_record,\n'
        '        {\n'
        '            "order_id_funpay": order_id_funpay,\n'
        '            "panel_order_id": panel_order_id,\n'
        '            "twiboost_id": panel_order_id,\n'
        '            "lot_title": active_record.get("lot_title") or active_record.get("service_name") or "—",\n'
        '        },\n'
        '    )\n'
        '\n'
        '    try:\n'
        '        c.send_message(buyer_chat_id, message)\n'
        '        order_record["completed_notification_sent"] = True\n'
        '        rt.logger.info(\n'
        '            f"Уведомление о завершении отправлено покупателю {buyer_chat_id} (заказ #{panel_order_id})."\n'
        '        )\n'
        '    except Exception as exc:\n'
        '        update_order_fields(order_id_funpay, completed_notification_sent=False)\n'
        '        order_record["completed_notification_sent"] = False\n'
        '        rt.logger.error(\n'
        '            f"Не удалось отправить уведомление о завершении для заказа #{order_id_funpay}: {exc}"\n'
        '        )\n'
        '\n'
        '\n'
        'def _send_lot_match_manual_alert(order_id_funpay: Any, description: Any, resolve_result: Dict[str, Any]) -> None:\n'
        '    """Alert admin chat when incoming order description matches zero or multiple lots."""\n'
        '    cfg = load_config()\n'
        '    notification_chat_id = cfg.get("notification_chat_id")\n'
        '    if not notification_chat_id or rt.bot is None:\n'
        '        return\n'
        '\n'
        '    error_code = str(resolve_result.get("error") or "unknown")\n'
        '    if error_code == "ambiguous_match":\n'
        '        lines = [\n'
        '            "⚠️ AutoSMM: найдено несколько подходящих лотов",\n'
        '            "",\n'
        '            f"Заказ FunPay: #{order_id_funpay}",\n'
        '            "Описание заказа:",\n'
