        '            "Совпадения:",\n'
        '        ]\n'
        '        for idx, item in enumerate(resolve_result.get("matches") or [], start=1):\n'
        '            lines.append(\n'
        '                f"{idx}. {item.get(\'lot_key\')} — {item.get(\'name\') or \'—\'} | "\n'
        '                f"ID услуги: {item.get(\'service_id\') or \'—\'} | "\n'
        '                f"Кол-во: {item.get(\'quantity\') or \'—\'} | "\n'
        '                f"Панель: {item.get(\'service_number\') or \'—\'}"\n'
        '            )\n'
        '        lines.extend(["", "Действие:", "проверьте привязку лота вручную."])\n'
        '    else:\n'
        '        lines = [\n'
        '            "⚠️ AutoSMM: не удалось определить лот",\n'
        '            "",\n'
        '            f"Заказ FunPay: #{order_id_funpay}",\n'
        '            "Описание заказа:",\n'
        '            str(description or "—"),\n'
        '            "",\n'
        '            "AutoSMM не нашёл подходящий лот в настройках.",\n'
        '            "",\n'
        '            "Действие:",\n'
        '            "проверьте привязки лотов вручную.",\n'
        '        ]\n'
        '\n'
        '    send_tg_notification(notification_chat_id, "\\n".join(lines))\n'
        '\n'
        '\n'
        'def _send_transport_error_after_add_alert(\n'
        '    order_id_funpay: Any,\n'
        '    service_number: Any,\n'
        '    service_id: Any,\n'
        '    real_amount: Any,\n'
        '    link_: str,\n'
        '    primary_error: Any,\n'
        '    primary_detail: Any,\n'
        '    balance_before: Optional[Dict[str, Any]] = None,\n'
