        '    auth_users = getattr(telegram_obj, "authorized_users", None)\n'
        '    if isinstance(auth_users, dict):\n'
        '        candidates.extend(auth_users.keys())\n'
        '    for raw_id in candidates:\n'
        '        if raw_id in (None, ""):\n'
        '            continue\n'
        '        try:\n'
        '            return int(raw_id)\n'
        '        except (TypeError, ValueError):\n'
        '            continue\n'
        '    return None\n'
        '\n'
        '\n'
        'def _build_telemetry_guest_warning_markup() -> Any:\n'
        '    from ..tg.telemetry import build_telemetry_guest_warning_markup\n'
        '    return build_telemetry_guest_warning_markup(TELEMETRY_SECURITY_URL)\n'
        '\n'
        '\n'
        'def _build_telemetry_guest_warning_text(tier: str, remaining_seconds: float) -> str:\n'
        '    remaining_label = _format_telemetry_guest_remaining(remaining_seconds)\n'
        '    header = (\n'
        '        "🚨 <b>Гостевой режим AutoSMM заканчивается менее чем через 12 часов</b>"\n'
        '        if tier == "12h"\n'
        '        else "⏳ <b>Напоминание о гостевом режиме AutoSMM</b>"\n'
        '    )\n'
        '    return (\n'
        '        f"{header}\\n\\n"\n'
        '        f"До окончания {TELEMETRY_GUEST_DAYS}-дневного гостевого режима осталось: <b>{remaining_label}</b>.\\n\\n"\n'
