        '        f"техническую статистику (или перейти на AutoSMM v0.0.8)."\n'
        '    )\n'
        '\n'
        '\n'
        'def _maybe_notify_telemetry_guest_expiring(\n'
        '    c: Optional[Cardinal] = None,\n'
        '    now_dt: Optional[datetime] = None,\n'
        ') -> Optional[str]:\n'
        '    """Notify admin once at <=48h and <=12h before the 7-day telemetry guest window expires."""\n'
        '    if not _GUEST_WARN_LOCK.acquire(blocking=False):\n'
        '        return None\n'
        '\n'
        '    try:\n'
        '        ref_dt = now_dt or datetime.now()\n'
        '        with STATE_LOCK:\n'
        '            state = _load_autosmm_state()\n'
        '            if state.get("telemetry_consent") is True or state.get("telemetry_guest_used") is not True:\n'
        '                return None\n'
        '            remaining = _get_telemetry_guest_remaining_seconds(state, now_dt=ref_dt)\n'
        '            if remaining is None or remaining <= 0:\n'
        '                return None\n'
        '\n'
        '            tier: Optional[str] = None\n'
        '            if remaining <= 12 * 3600 and not state.get("telemetry_guest_warn_12h_sent_at"):\n'
        '                tier = "12h"\n'
        '            elif 12 * 3600 < remaining <= 48 * 3600 and not state.get("telemetry_guest_warn_48h_sent_at"):\n'
        '                tier = "48h"\n'
        '            if not tier:\n'
        '                return None\n'
        '            state_snapshot = dict(state)\n'
        '\n'
        '        target_chat_id = _resolve_telemetry_warning_chat_id(c, state_snapshot)\n'
        '        if target_chat_id is None:\n'
        '            return None\n'
        '\n'
        '        success = send_tg_notification(\n'
        '            target_chat_id,\n'
        '            _build_telemetry_guest_warning_text(tier, remaining),\n'
        '            reply_markup=_build_telemetry_guest_warning_markup(),\n'
        '            parse_mode="HTML",\n'
        '            disable_web_page_preview=True,\n'
        '            cardinal=c,\n'
        '        )\n'
        '        if not success:\n'
        '            rt.logger.warning(f"TELEMETRY GUEST WARNING ({tier}) FAILED")\n'
        '            return None\n'
        '\n'
        '        sent_at = ref_dt.isoformat(timespec="seconds")\n'
        '        with STATE_LOCK:\n'
        '            latest_state = _load_autosmm_state()\n'
        '            if not latest_state.get("telemetry_guest_warn_48h_sent_at"):\n'
        '                latest_state["telemetry_guest_warn_48h_sent_at"] = sent_at\n'
        '            if tier == "12h":\n'
        '                latest_state["telemetry_guest_warn_12h_sent_at"] = sent_at\n'
        '            _save_autosmm_state(latest_state)\n'
        '        return tier\n'
        '    finally:\n'
        '        _GUEST_WARN_LOCK.release()\n'
        '\n'
        '\n'
        'def _get_funpay_identity(c: Optional[Cardinal] = None) -> Tuple[str, str, str]:\n'
        '    return _telemetry_get_funpay_identity(c, fallback=rt.cardinal_instance)\n'
        '\n'
        '\n'
        'def _get_anonymous_install_id(c: Optional[Cardinal] = None) -> str:\n'
        '    with STATE_LOCK:\n'
        '        state = _load_autosmm_state()\n'
