        '    "auto_smm_state.json": {},\n'
        '}\n'
        '\n'
        '\n'
        'def get_backup_file_map() -> Dict[str, str]:\n'
        '    """Return mapping of JSON config backup filenames to active storage paths."""\n'
        '    return {\n'
        '        "auto_lots.json": rt.CONFIG_PATH,\n'
        '        "valid_link.json": rt.VALID_LINKS_PATH,\n'
        '    }\n'
        '\n'
        '\n'
        'def _backup_default_for_file(file_name: str) -> Any:\n'
        '    default_value = AUTOSMM_BACKUP_DEFAULTS.get(file_name, {})\n'
        '    if isinstance(default_value, (dict, list)):\n'
