        '    return _safe_load_json(path, _backup_default_for_file(file_name))\n'
        '\n'
        '\n'
        'def _build_full_backup_payload(reason: str = "manual_export") -> Dict[str, Any]:\n'
        '    with CONFIG_LOCK, ORDERS_LOCK, STATE_LOCK:\n'
        '        snapshot = db_state.export_snapshot()\n'
