        '\n'
        'MAX_BACKUP_FILES_TO_KEEP = 20\n'
        '\n'
        '\n'
        'def _prune_old_backups(backups_dir: str, max_keep: int = MAX_BACKUP_FILES_TO_KEEP) -> None:\n'
        '    if max_keep < 1 or not os.path.isdir(backups_dir):\n'
        '        return\n'
        '    try:\n'
        '        entries = [\n'
