        '            for srv_key, srv_cfg in services_payload.items():\n'
        '                if not isinstance(srv_cfg, dict):\n'
        '                    return False, f"В бэкапе некорректная запись сервиса #{srv_key} в auto_lots.json."\n'
        '                raw_api_url = str(srv_cfg.get("api_url") or "").strip()\n'
