        '        if "lot_mapping" in cfg_payload and not isinstance(cfg_payload["lot_mapping"], dict):\n'
        '            return False, "В бэкапе некорректный раздел lot_mapping в auto_lots.json."\n'
        '\n'
        '    if version == 1:\n'
        '        raw_orders = files.get("orders_data.json")\n'
        '        if raw_orders is not None:\n'
        '            if not isinstance(raw_orders, list):\n'
        '                return False, "В бэкапе некорректный формат файла orders_data.json."\n'
        '            for idx, ord_entry in enumerate(raw_orders):\n'
