        '\n'
        '    if version == 2:\n'
        '        orders = payload.get("orders")\n'
        '        if not isinstance(orders, list):\n'
        '            return False, "В бэкапе некорректный раздел orders."\n'
        '        for idx, ord_entry in enumerate(orders):\n'
