        '\n'
        '\n'
        'def get_db_lock(db_path: Optional[str] = None) -> threading.RLock:\n'
        '    """Return a per-database-path reentrant lock to serialize writers safely."""\n'
        '    key = os.path.normcase(_resolve_db_path(db_path))\n'
        '    with _DB_LOCKS_GUARD:\n'
        '        lock = _DB_LOCKS.get(key)\n'
        '        if lock is None:\n'
        '            lock = threading.RLock()\n'
        '            _DB_LOCKS[key] = lock\n'
        '        return lock\n'
        '\n'
        '\n'
        'def _migrate_schema_columns(conn: sqlite3.Connection) -> None:\n'
        '    conn.execute("PRAGMA journal_mode=WAL;")\n'
        '    conn.execute("CREATE TABLE IF NOT EXISTS schema_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)")\n'
        '    cols = {str(r["name"]) for r in conn.execute("PRAGMA table_info(orders)").fetchall()}\n'
        '    if "spent_rub" not in cols:\n'
        '        conn.execute("ALTER TABLE orders ADD COLUMN spent_rub REAL")\n'
        '    if "fx_rate_to_rub" not in cols:\n'
        '        conn.execute("ALTER TABLE orders ADD COLUMN fx_rate_to_rub REAL")\n'
        '    conn.execute(\n'
        '        "INSERT OR REPLACE INTO schema_meta (key, value) VALUES (?, ?)",\n'
        '        ("schema_version", SCHEMA_VERSION),\n'
        '    )\n'
        '\n'
        '\n'
        'def _has_current_schema_version(conn: sqlite3.Connection) -> bool:\n'
        '    has_meta = conn.execute(\n'
        '        "SELECT name FROM sqlite_master WHERE type=\'table\' AND name=\'schema_meta\'"\n'
        '    ).fetchone()\n'
        '    if has_meta is None:\n'
        '        return False\n'
        '    row = conn.execute(\n'
        '        "SELECT value FROM schema_meta WHERE key = \'schema_version\'"\n'
        '    ).fetchone()\n'
        '    return row is not None and str(row[0]) == SCHEMA_VERSION\n'
        '\n'
        '\n'
        'def _ensure_schema(conn: sqlite3.Connection) -> None:\n'
        '    row = conn.execute(\n'
        '        "SELECT name FROM sqlite_master WHERE type=\'table\' AND name=\'orders\'"\n'
        '    ).fetchone()\n'
        '    if row is not None:\n'
        '        if not _has_current_schema_version(conn):\n'
        '            _migrate_schema_columns(conn)\n'
        '        return\n'
        '    conn.execute("PRAGMA journal_mode=WAL;")\n'
        '    conn.executescript(_SCHEMA_SQL)\n'
        '    conn.execute(\n'
        '        "INSERT OR REPLACE INTO schema_meta (key, value) VALUES (?, ?)",\n'
        '        ("schema_version", SCHEMA_VERSION),\n'
        '    )\n'
        '\n'
        '\n'
        'def _stat_signature(path: str) -> Optional[Tuple[int, int, int]]:\n'
        '    try:\n'
        '        st = os.stat(path)\n'
        '    except OSError:\n'
        '        return None\n'
        '    ino = int(getattr(st, "st_ino", 0) or 0)\n'
        '    ctime = int(getattr(st, "st_ctime_ns", 0) or int(getattr(st, "st_ctime", 0)))\n'
        '    if ino:\n'
        '        return (int(st.st_dev), ino, ctime)\n'
        '    mtime = int(getattr(st, "st_mtime_ns", 0) or int(getattr(st, "st_mtime", 0)))\n'
        '    return (int(st.st_size), mtime, ctime)\n'
        '\n'
        '\n'
        'def _mark_db_initialized(target: str) -> None:\n'
        '    key = os.path.normcase(target)\n'
        '    sig = _stat_signature(target)\n'
        '    if sig is None:\n'
        '        return\n'
        '    with _SCHEMA_CACHE_LOCK:\n'
        '        _INITIALIZED_DB_SIGNATURES[key] = sig\n'
        '\n'
        '\n'
        'def invalidate_schema_cache(db_path: Optional[str] = None) -> None:\n'
        '    """Forget cached schema initialization state so the next access re-verifies the DB file."""\n'
        '    with _SCHEMA_CACHE_LOCK:\n'
        '        if db_path is None:\n'
        '            _INITIALIZED_DB_SIGNATURES.clear()\n'
        '            return\n'
        '        _INITIALIZED_DB_SIGNATURES.pop(os.path.normcase(_resolve_db_path(db_path)), None)\n'
        '\n'
        '\n'
        'def _is_db_schema_cached(target: str) -> bool:\n'
        '    key = os.path.normcase(target)\n'
        '    current_sig = _stat_signature(target)\n'
        '    if current_sig is None:\n'
        '        return False\n'
        '    with _SCHEMA_CACHE_LOCK:\n'
        '        return _INITIALIZED_DB_SIGNATURES.get(key) == current_sig\n'
        '\n'
        '\n'
        'def _ensure_db_initialized(target: str) -> None:\n'
        '    if _is_db_schema_cached(target):\n'
        '        return\n'
        '    init_db(target)\n'
        '\n'
        '\n'
        '@contextmanager\n'
        'def _connect(db_path: Optional[str] = None, *, read_only: bool = False) -> Iterator[sqlite3.Connection]:\n'
        '    target = _resolve_db_path(db_path)\n'
        '    if read_only:\n'
        '        _ensure_db_initialized(target)\n'
        '        conn = sqlite3.connect(target, timeout=DEFAULT_CONNECT_TIMEOUT)\n'
        '        conn.row_factory = sqlite3.Row\n'
        '        try:\n'
        '            conn.execute("PRAGMA busy_timeout=10000;")\n'
        '            conn.execute("PRAGMA query_only=ON;")\n'
        '            yield conn\n'
        '        finally:\n'
        '            conn.close()\n'
        '        return\n'
        '\n'
        '    parent = os.path.dirname(target)\n'
        '    if parent:\n'
        '        os.makedirs(parent, exist_ok=True)\n'
        '    with get_db_lock(target):\n'
        '        conn = sqlite3.connect(target, timeout=DEFAULT_CONNECT_TIMEOUT)\n'
        '        conn.row_factory = sqlite3.Row\n'
        '        try:\n'
        '            conn.execute("PRAGMA busy_timeout=10000;")\n'
        '            conn.execute("PRAGMA synchronous=NORMAL;")\n'
        '            _ensure_schema(conn)\n'
        '            yield conn\n'
        '            conn.commit()\n'
        '        except Exception:\n'
        '            conn.rollback()\n'
        '            raise\n'
        '        finally:\n'
        '            conn.close()\n'
        '        _mark_db_initialized(target)\n'
        '\n'
        '\n'
        'def init_db(db_path: Optional[str] = None) -> None:\n'
        '    """Ensure the SQLite database file, schema tables, and indexes exist."""\n'
        '    with _connect(db_path, read_only=False):\n'
        '        pass\n'
