        '\n'
        'def _json_loads_optional(raw_value: Optional[str], default: Any = None) -> Any:\n'
        '    if raw_value in (None, ""):\n'
        '        return default\n'
        '    try:\n'
        '        return json.loads(raw_value)\n'
        '    except (ValueError, TypeError):\n'
