        '    status_stop_reason = excluded.status_stop_reason,\n'
        '    manual_check_alert_sent = excluded.manual_check_alert_sent,\n'
        '    funpay_status_checked_at = excluded.funpay_status_checked_at,\n'
        '    refund_detected_at = excluded.refund_detected_at,\n'
        '    refund_source = excluded.refund_source,\n'
        '    panel_refund_cancel_attempted_at = excluded.panel_refund_cancel_attempted_at,\n'
        '    panel_refund_cancel_result = excluded.panel_refund_cancel_result,\n'
        '    last_prompt_ts = excluded.last_prompt_ts,\n'
        '    created_at = excluded.created_at,\n'
        '    updated_at = excluded.updated_at,\n'
        '    date = excluded.date,\n'
        '    extra_json = excluded.extra_json\n'
        '"""\n'
        '\n'
        '\n'
        'def _normalize_fallback_pair(fallback_used: Any, fallback_reason: Any) -> Tuple[Optional[int], Optional[str]]:\n'
        '    if fallback_used is True:\n'
        '        reason = None if fallback_reason in (None, "") else str(fallback_reason)\n'
        '        return 1, reason\n'
        '    if fallback_reason not in (None, ""):\n'
        '        return 0, str(fallback_reason)\n'
        '    return None, None\n'
        '\n'
        '\n'
        'def _decode_order_row_metadata(data: Dict[str, Any], row: sqlite3.Row) -> None:\n'
        '    for key in _ROW_OPTIONAL_TEXT_KEYS:\n'
        '        val = row[key]\n'
        '        if val not in (None, ""):\n'
        '            data[key] = val\n'
        '\n'
        '    panel_order_id = row["panel_order_id"]\n'
        '    if panel_order_id is not None:\n'
        '        panel_oid = int(panel_order_id)\n'
        '        data["panel_order_id"] = panel_oid\n'
        '        data["id_zakaz"] = panel_oid\n'
        '    else:\n'
        '        data["id_zakaz"] = None\n'
        '\n'
        '    for key in ("total_quantity", "done_quantity", "left_quantity", "progress_percent"):\n'
        '        data[key] = int(row[key] or 0)\n'
        '\n'
        '    for col, target in (("order_amount_json", "order_amount"), ("order_price_json", "order_price")):\n'
        '        parsed = _json_loads_optional(row[col], None)\n'
        '        if parsed is not None:\n'
        '            data[target] = parsed\n'
        '\n'
        '    if row["fallback_used"] is not None:\n'
        '        data["fallback_used"] = bool(row["fallback_used"])\n'
        '        if row["fallback_reason"] not in (None, ""):\n'
        '            data["fallback_reason"] = row["fallback_reason"]\n'
        '    elif row["fallback_reason"] not in (None, ""):\n'
        '        data["fallback_used"] = False\n'
        '        data["fallback_reason"] = row["fallback_reason"]\n'
        '\n'
        '    if row["date"] not in (None, ""):\n'
        '        data["date"] = row["date"]\n'
        '        data["date_str"] = row["date"]\n'
        '\n'
        '\n'
        'def _row_to_order_dict(row: sqlite3.Row) -> Dict[str, Any]:\n'
        '    data: Dict[str, Any] = {\n'
        '        "order_id": str(row["order_id"]),\n'
        '        "status": str(row["status"] or "pending"),\n'
        '        "customer_url": str(row["customer_url"] or ""),\n'
        '        "quantity": int(row["quantity"] or 0),\n'
        '        "service_number": int(row["service_number"] if row["service_number"] is not None else 1),\n'
        '        "summa": float(row["summa"] or 0.0),\n'
        '        "spent": float(row["spent"] or 0.0),\n'
        '        "chistota": float(row["chistota"] or 0.0),\n'
        '        "currency": str(row["currency"] or "RUB"),\n'
        '        "created_at": int(row["created_at"] or 0),\n'
        '        "completed_notification_sent": bool(row["completed_notification_sent"]),\n'
        '        "incorrect_order_id_attempts": int(row["incorrect_order_id_attempts"] or 0),\n'
        '        "manual_check_alert_sent": bool(row["manual_check_alert_sent"]),\n'
        '    }\n'
        '    if row["spent_rub"] is not None:\n'
        '        data["spent_rub"] = float(row["spent_rub"])\n'
        '    if row["fx_rate_to_rub"] is not None:\n'
        '        data["fx_rate_to_rub"] = float(row["fx_rate_to_rub"])\n'
        '    if row["chat_id"] is not None:\n'
        '        data["chat_id"] = normalize_chat_id(row["chat_id"])\n'
        '    if row["service_id"] is not None:\n'
        '        data["service_id"] = int(row["service_id"])\n'
        '\n'
        '    buyer_id = _json_loads_optional(row["buyer_id_json"], None)\n'
        '    if buyer_id is None and row["buyer_id"] is not None:\n'
        '        buyer_id = row["buyer_id"]\n'
        '    if buyer_id is not None:\n'
        '        data["buyer_id"] = buyer_id\n'
        '\n'
        '    _decode_order_row_metadata(data, row)\n'
        '\n'
        '    extra = _json_loads_optional(row["extra_json"], {})\n'
        '    if isinstance(extra, dict):\n'
        '        for key, value in extra.items():\n'
        '            if key not in data and value is not None:\n'
        '                data[key] = value\n'
        '    return data\n'
        '\n'
        '\n'
        'def _prepare_order_params(raw: Mapping[str, Any]) -> Optional[Tuple[Any, ...]]:\n'
        '    order_id = str(raw.get("order_id") or "").strip()\n'
        '    if not order_id:\n'
        '        return None\n'
        '\n'
        '    buyer_raw = raw.get("buyer_id")\n'
        '    raw_summa = raw.get("summa")\n'
        '    if raw_summa is None:\n'
        '        raw_summa = raw.get("order_price", 0.0)\n'
        '    summa = safe_float(raw_summa, 0.0)\n'
        '    chistota_raw = raw.get("chistota")\n'
        '    chistota = summa if chistota_raw is None else safe_float(chistota_raw, 0.0)\n'
        '    fallback_used_int, fallback_reason = _normalize_fallback_pair(\n'
        '        raw.get("fallback_used"),\n'
        '        raw.get("fallback_reason"),\n'
        '    )\n'
        '\n'
        '    progress = extract_progress_values(raw)\n'
        '    total_qty = safe_int(raw.get("total_quantity"))\n'
        '    done_qty = safe_int(raw.get("done_quantity"))\n'
        '    left_qty = safe_int(raw.get("left_quantity"))\n'
        '    prog_pct = safe_int(raw.get("progress_percent"))\n'
        '\n'
        '    date_val = raw.get("date") or raw.get("date_str")\n'
        '    extra = {k: v for k, v in raw.items() if k not in _KNOWN_ORDER_KEYS and v is not None}\n'
        '\n'
        '    def _clean(key: str) -> Optional[str]:\n'
        '        val = raw.get(key)\n'
        '        return None if val in (None, "") else str(val)\n'
        '\n'
        '    return (\n'
        '        order_id,\n'
        '        normalize_chat_id(raw.get("chat_id")),\n'
        '        None if buyer_raw is None else str(buyer_raw),\n'
        '        _json_dumps_optional(buyer_raw),\n'
        '        str(raw.get("buyer_username") or ""),\n'
        '        str(raw.get("lot_title") or ""),\n'
        '        str(raw.get("service_name") or ""),\n'
        '        safe_int(raw.get("service_id")),\n'
        '        safe_int(raw.get("service_number")) if raw.get("service_number") is not None else 1,\n'
        '        resolve_panel_order_id(raw),\n'
        '        str(raw.get("status") or "pending"),\n'
        '        _clean("panel_status"),\n'
        '        get_effective_funpay_status(raw),\n'
        '        _clean("buyer_flow_state"),\n'
        '        str(raw.get("customer_url") or ""),\n'
        '        _clean("saved_link"),\n'
        '        safe_int(raw.get("quantity")) or 0,\n'
        '        total_qty if total_qty is not None else progress["total_quantity"],\n'
        '        done_qty if done_qty is not None else progress["done_quantity"],\n'
        '        left_qty if left_qty is not None else progress["left_quantity"],\n'
        '        prog_pct if prog_pct is not None else progress["progress_percent"],\n'
        '        _json_dumps_optional(raw.get("order_amount")),\n'
        '        _json_dumps_optional(raw.get("order_price")),\n'
        '        summa,\n'
        '        safe_float(raw.get("spent"), 0.0),\n'
        '        optional_float(raw.get("spent_rub")),\n'
        '        optional_float(raw.get("fx_rate_to_rub")),\n'
        '        chistota,\n'
        '        str(raw.get("currency") or "RUB"),\n'
        '        fallback_used_int,\n'
        '        fallback_reason,\n'
        '        1 if bool(raw.get("completed_notification_sent", False)) else 0,\n'
        '        _clean("status_last_checked_at"),\n'
        '        _clean("status_last_error"),\n'
        '        safe_int(raw.get("incorrect_order_id_attempts")) or 0,\n'
        '        _clean("status_stop_reason"),\n'
        '        1 if bool(raw.get("manual_check_alert_sent", False)) else 0,\n'
        '        _clean("funpay_status_checked_at"),\n'
        '        _clean("refund_detected_at"),\n'
        '        _clean("refund_source"),\n'
        '        _clean("panel_refund_cancel_attempted_at"),\n'
        '        _clean("panel_refund_cancel_result"),\n'
        '        _clean("last_prompt_ts"),\n'
        '        safe_int(raw.get("created_at")) or 0,\n'
        '        _clean("updated_at"),\n'
        '        None if date_val in (None, "") else str(date_val),\n'
        '        json.dumps(extra, ensure_ascii=False),\n'
        '    )\n'
        '\n'
        '\n'
        'def get_order(order_id: str, db_path: Optional[str] = None) -> Optional[Dict[str, Any]]:\n'
        '    """Fetch a single order by FunPay order ID."""\n'
        '    target_id = str(order_id or "").strip()\n'
        '    if not target_id:\n'
        '        return None\n'
        '    with _connect(db_path, read_only=True) as conn:\n'
        '        row = conn.execute("SELECT * FROM orders WHERE order_id = ?", (target_id,)).fetchone()\n'
        '        return _row_to_order_dict(row) if row is not None else None\n'
        '\n'
        '\n'
        'def list_orders(\n'
        '    db_path: Optional[str] = None,\n'
        '    *,\n'
        '    status: Optional[str] = None,\n'
        '    exclude_statuses: Optional[Iterable[str]] = None,\n'
        ') -> List[Dict[str, Any]]:\n'
        '    """Return orders ordered by creation timestamp, optionally filtered by status."""\n'
        '    clauses: List[str] = []\n'
        '    params: List[Any] = []\n'
        '    if status is not None:\n'
        '        clauses.append("status = ?")\n'
        '        params.append(str(status))\n'
        '    if exclude_statuses:\n'
        '        excluded = [str(item) for item in exclude_statuses]\n'
        '        placeholders = ", ".join("?" for _ in excluded)\n'
        '        clauses.append(f"status NOT IN ({placeholders})")\n'
        '        params.extend(excluded)\n'
        '    where_sql = f"WHERE {\' AND \'.join(clauses)}" if clauses else ""\n'
        '    sql = f"SELECT * FROM orders {where_sql} ORDER BY created_at ASC, rowid ASC"\n'
        '    with _connect(db_path, read_only=True) as conn:\n'
        '        rows = conn.execute(sql, params).fetchall()\n'
        '        return [_row_to_order_dict(row) for row in rows]\n'
        '\n'
        '\n'
        'def get_order_record(order_id: str, db_path: Optional[str] = None) -> Optional[OrderRecord]:\n'
        '    """Fetch a single order and return a strongly typed OrderRecord."""\n'
        '    data = get_order(order_id, db_path=db_path)\n'
        '    return OrderRecord.from_dict(data) if data is not None else None\n'
        '\n'
        '\n'
        'def list_order_records(\n'
        '    db_path: Optional[str] = None,\n'
        '    *,\n'
        '    status: Optional[str] = None,\n'
        '    exclude_statuses: Optional[Iterable[str]] = None,\n'
        ') -> List[OrderRecord]:\n'
        '    """Return orders as strongly typed OrderRecords."""\n'
        '    return [\n'
        '        OrderRecord.from_dict(d)\n'
        '        for d in list_orders(db_path=db_path, status=status, exclude_statuses=exclude_statuses)\n'
        '    ]\n'
        '\n'
        '\n'
        'def replace_all_orders(orders: Iterable[Mapping[str, Any]], db_path: Optional[str] = None) -> bool:\n'
        '    """Replace all rows in the orders table within one atomic transaction."""\n'
        '    with _connect(db_path) as conn:\n'
        '        conn.execute("DELETE FROM orders")\n'
        '        params_list = [\n'
        '            prepared\n'
        '            for item in (orders or [])\n'
        '            if isinstance(item, Mapping) and (prepared := _prepare_order_params(item)) is not None\n'
        '        ]\n'
        '        if params_list:\n'
        '            conn.executemany(_UPSERT_ORDER_SQL, params_list)\n'
        '    return True\n'
        '\n'
        '\n'
        'def upsert_order_dict(order: Mapping[str, Any], db_path: Optional[str] = None) -> Optional[Dict[str, Any]]:\n'
        '    """Insert or update an order row from a full dictionary."""\n'
        '    prepared = _prepare_order_params(order)\n'
        '    if prepared is None:\n'
        '        return None\n'
        '    target_id = str(prepared[0])\n'
        '    with _connect(db_path) as conn:\n'
        '        conn.execute(_UPSERT_ORDER_SQL, prepared)\n'
        '        row = conn.execute("SELECT * FROM orders WHERE order_id = ?", (target_id,)).fetchone()\n'
        '        return _row_to_order_dict(row) if row is not None else None\n'
        '\n'
        '\n'
        'def _apply_fallback_fields(target: Dict[str, Any], fallback_used: Any, fallback_reason: Any) -> None:\n'
        '    if fallback_used is True:\n'
        '        target["fallback_used"] = True\n'
        '        if fallback_reason not in (None, ""):\n'
        '            target["fallback_reason"] = fallback_reason\n'
        '        else:\n'
        '            target.pop("fallback_reason", None)\n'
        '    elif fallback_reason not in (None, ""):\n'
        '        target["fallback_used"] = False\n'
        '        target["fallback_reason"] = fallback_reason\n'
        '    else:\n'
        '        target.pop("fallback_used", None)\n'
        '        target.pop("fallback_reason", None)\n'
        '\n'
        '\n'
        'def upsert_order(\n'
        '    chat_id: int,\n'
        '    order_id: str,\n'
        '    panel_order_id: Optional[int],\n'
        '    status: str,\n'
        '    chistota: float,\n'
        '    customer_url: str,\n'
        '    quantity: int,\n'
        '    service_number: int,\n'
        '    is_refunded: bool = False,\n'
        '    fallback_used: Optional[bool] = False,\n'
        '    fallback_reason: Optional[str] = None,\n'
        '    funpay_status: Optional[str] = None,\n'
        '    db_path: Optional[str] = None,\n'
        '    **extra_fields: Any,\n'
        ') -> Dict[str, Any]:\n'
        '    """Create or update an order while preserving existing accounting/runtime attributes."""\n'
        '    target_id = str(order_id or "").strip()\n'
        '    now_ts = int(time.time())\n'
        '    with _connect(db_path) as conn:\n'
        '        existing_row = conn.execute("SELECT * FROM orders WHERE order_id = ?", (target_id,)).fetchone()\n'
        '        existing = _row_to_order_dict(existing_row) if existing_row is not None else {}\n'
        '\n'
        '        existing_fp = normalize_funpay_status(existing.get("funpay_status"))\n'
        '        if is_refunded_funpay_status(existing_fp) or is_refunded:\n'
        '            normalized_funpay_status = "refunded"\n'
        '        else:\n'
        '            normalized_funpay_status = (\n'
        '                normalize_funpay_status(funpay_status)\n'
        '                or existing_fp\n'
        '                or "open"\n'
        '            )\n'
        '\n'
        '        existing_summa = safe_float(existing.get("summa"), 0.0)\n'
        '        existing_spent = safe_float(existing.get("spent"), 0.0)\n'
        '        existing_chistota = safe_float(existing.get("chistota"), 0.0)\n'
        '        incoming_chistota = safe_float(chistota, 0.0)\n'
        '\n'
        '        merged = dict(existing)\n'
        '        merged.update(\n'
        '            {\n'
        '                "order_id": target_id,\n'
        '                "chat_id": normalize_chat_id(chat_id),\n'
        '                "panel_order_id": panel_order_id,\n'
        '                "id_zakaz": panel_order_id,\n'
        '                "status": status,\n'
        '                "customer_url": customer_url,\n'
        '                "quantity": quantity,\n'
        '                "service_number": service_number,\n'
        '                "funpay_status": normalized_funpay_status,\n'
        '                "summa": existing_summa if existing_summa > 0.0 else incoming_chistota,\n'
        '                "spent": existing_spent,\n'
        '                "chistota": existing_chistota if (existing_chistota != 0.0 or existing_spent > 0.0) else incoming_chistota,\n'
        '                "currency": str(existing.get("currency") or "RUB"),\n'
        '                "created_at": safe_int(existing.get("created_at")) or now_ts,\n'
        '                "completed_notification_sent": bool(existing.get("completed_notification_sent", False)),\n'
        '            }\n'
        '        )\n'
        '        merged.pop("is_refunded", None)\n'
        '        _apply_fallback_fields(merged, fallback_used, fallback_reason)\n'
        '\n'
        '        for key, value in extra_fields.items():\n'
        '            if value is not None:\n'
        '                merged[key] = value\n'
        '\n'
        '        prepared = _prepare_order_params(merged)\n'
        '        if prepared is None:\n'
        '            raise ValueError(f"Invalid order_id for upsert_order: {order_id!r}")\n'
        '        conn.execute(_UPSERT_ORDER_SQL, prepared)\n'
        '        row = conn.execute("SELECT * FROM orders WHERE order_id = ?", (target_id,)).fetchone()\n'
        '        result = _row_to_order_dict(row) if row is not None else merged\n'
        '    logger.info(\n'
        '        f"Данные заказа #{target_id} (panel order ID: {panel_order_id}) сохранены/обновлены. "\n'
        '        f"fallback_used={(bool(fallback_used) if fallback_used or fallback_reason not in (None, \'\') else \'not_set\')}, "\n'
        '        f"fallback_reason={fallback_reason}"\n'
        '    )\n'
        '    return result\n'
        '\n'
        '\n'
        'def _apply_partial_order_field(order: Dict[str, Any], key: str, value: Any) -> None:\n'
        '    if key == "funpay_status":\n'
        '        norm_status = normalize_funpay_status(value)\n'
        '        if norm_status:\n'
        '            order["funpay_status"] = norm_status\n'
        '        elif value is None:\n'
        '            order.pop("funpay_status", None)\n'
        '        return\n'
        '    if key in ("id_zakaz", "twiboost_id", "panel_order_id"):\n'
        '        oid_val = safe_int(value)\n'
        '        if oid_val is None:\n'
        '            order.pop("panel_order_id", None)\n'
        '            order.pop("id_zakaz", None)\n'
        '        else:\n'
        '            order["panel_order_id"] = oid_val\n'
        '            order["id_zakaz"] = oid_val\n'
        '        return\n'
        '    if key in ("date", "date_str"):\n'
        '        if value in (None, ""):\n'
        '            order.pop("date", None)\n'
        '            order.pop("date_str", None)\n'
        '        else:\n'
        '            order["date"] = str(value)\n'
        '            order["date_str"] = str(value)\n'
        '        return\n'
        '    if value is None or (key in _NULLABLE_TEXT_FIELDS and value == ""):\n'
        '        order.pop(key, None)\n'
        '    else:\n'
        '        order[key] = value\n'
        '\n'
        '\n'
        'def update_order_fields(order_id: str, db_path: Optional[str] = None, **fields: Any) -> bool:\n'
        '    """Partially update selected fields on an existing order row."""\n'
        '    target_id = str(order_id or "").strip()\n'
        '    if not target_id:\n'
        '        return False\n'
        '    with _connect(db_path) as conn:\n'
        '        row = conn.execute("SELECT * FROM orders WHERE order_id = ?", (target_id,)).fetchone()\n'
        '        if row is None:\n'
        '            logger.warning(f"Заказ #{target_id} не найден в базе данных.")\n'
        '            return False\n'
        '\n'
        '        order = _row_to_order_dict(row)\n'
        '        for key, value in fields.items():\n'
        '            if key not in ("fallback_used", "fallback_reason", "is_refunded"):\n'
        '                _apply_partial_order_field(order, key, value)\n'
        '\n'
        '        if "fallback_used" in fields or "fallback_reason" in fields:\n'
        '            _apply_fallback_fields(order, fields.get("fallback_used"), fields.get("fallback_reason"))\n'
        '\n'
        '        prepared = _prepare_order_params(order)\n'
        '        if prepared is None:\n'
        '            return False\n'
        '        conn.execute(_UPSERT_ORDER_SQL, prepared)\n'
        '    return True\n'
        '\n'
        '\n'
        'def mark_order_refunded_atomic(\n'
        '    order_id: str,\n'
        '    *,\n'
        '    detected_at: Optional[str] = None,\n'
        '    source: Optional[str] = None,\n'
        '    db_path: Optional[str] = None,\n'
        ') -> Tuple[bool, Optional[Dict[str, Any]], bool]:\n'
        '    """Atomically mark an order refunded and return (updated, snapshot, found)."""\n'
        '    target_id = str(order_id or "").strip()\n'
        '    if not target_id:\n'
        '        return False, None, False\n'
        '\n'
        '    ts_now = detected_at or rt.now_str()\n'
        '    src = source or "refund_mark"\n'
        '    with _connect(db_path) as conn:\n'
        '        row = conn.execute("SELECT * FROM orders WHERE order_id = ?", (target_id,)).fetchone()\n'
        '        if row is None:\n'
        '            return False, None, False\n'
        '\n'
        '        current = _row_to_order_dict(row)\n'
        '        if is_refunded_funpay_status(get_effective_funpay_status(current)):\n'
        '            return False, current, True\n'
        '\n'
        '        current["funpay_status"] = "refunded"\n'
        '        current["buyer_flow_state"] = BuyerFlowState.REFUNDED.value\n'
        '        current.pop("saved_link", None)\n'
        '        current["refund_detected_at"] = ts_now\n'
        '        current["refund_source"] = src\n'
        '        current["updated_at"] = ts_now\n'
        '\n'
        '        prepared = _prepare_order_params(current)\n'
        '        if prepared is None:\n'
        '            return False, current, True\n'
        '        conn.execute(_UPSERT_ORDER_SQL, prepared)\n'
        '        updated_row = conn.execute("SELECT * FROM orders WHERE order_id = ?", (target_id,)).fetchone()\n'
        '        snapshot = _row_to_order_dict(updated_row) if updated_row is not None else current\n'
