        '        if row is not None:\n'
        '            current = _row_to_order_dict(row)\n'
        '            if is_refunded_funpay_status(get_effective_funpay_status(current)):\n'
        '                return False, "refunded", current\n'
        '            if resolve_panel_order_id(current) is not None:\n'
        '                return False, "panel_created", current\n'
        '            flow_state = str(current.get("buyer_flow_state") or "").strip().lower()\n'
        '            stop_reason = str(current.get("status_stop_reason") or "").strip().lower()\n'
        '            panel_status_val = str(current.get("panel_status") or "").strip().lower()\n'
