        '                "chat_id": normalize_chat_id(seed.get("chat_id")),\n'
        '                "buyer_id": seed.get("buyer_id"),\n'
        '                "buyer_username": str(seed.get("buyer_username") or ""),\n'
        '                "lot_title": str(seed.get("lot_title") or ""),\n'
        '                "service_name": str(seed.get("lot_title") or seed.get("service_name") or "—"),\n'
        '                "service_id": safe_int(seed.get("service_id")),\n'
        '                "service_number": svc_num,\n'
        '                "quantity": safe_int(seed.get("quantity")) or 0,\n'
        '                "total_quantity": safe_int(seed.get("quantity")) or 0,\n'
        '                "left_quantity": safe_int(seed.get("quantity")) or 0,\n'
        '                "summa": safe_float(seed.get("summa"), 0.0),\n'
        '                "spent": 0.0,\n'
        '                "chistota": 0.0,\n'
        '                "currency": "RUB",\n'
        '                "funpay_status": "open",\n'
        '                "created_at": safe_int(seed.get("created_at")) or int(time.time()),\n'
        '                "date": str(seed.get("date") or ts_now),\n'
        '            }\n'
        '            for optional_key in ("lot_key", "order_amount", "order_price"):\n'
        '                if seed.get(optional_key) is not None:\n'
        '                    merged[optional_key] = seed[optional_key]\n'
        '\n'
        '        merged.update(\n'
        '            {\n'
        '                "order_id": target_id,\n'
        '                "panel_add_submitted": True,\n'
        '                "panel_add_attempted_at": ts_now,\n'
        '                "panel_add_service_number": svc_num,\n'
        '                "buyer_flow_state": BuyerFlowState.FAILED.value,\n'
        '                "status": "unknown",\n'
        '                "panel_status": "manual_check",\n'
        '                "status_stop_reason": "panel_add_in_flight",\n'
        '                "saved_link": saved_link,\n'
        '                "customer_url": saved_link,\n'
        '                "updated_at": ts_now,\n'
        '            }\n'
        '        )\n'
        '        prepared = _prepare_order_params(merged)\n'
        '        if prepared is None:\n'
        '            return False, "invalid_order_id", None\n'
        '        conn.execute(_UPSERT_ORDER_SQL, prepared)\n'
        '        updated_row = conn.execute("SELECT * FROM orders WHERE order_id = ?", (target_id,)).fetchone()\n'
        '        snapshot = _row_to_order_dict(updated_row) if updated_row is not None else merged\n'
        '    return True, "claimed", snapshot\n'
        '\n'
