        'def rename_orders_service_number(\n'
        '    old_service_number: int,\n'
        '    new_service_number: int,\n'
        '    db_path: Optional[str] = None,\n'
        ') -> int:\n'
        '    """Update order service_number references atomically when a panel number is renamed."""\n'
        '    old_num = safe_int(old_service_number)\n'
        '    new_num = safe_int(new_service_number)\n'
        '    if old_num is None or new_num is None or old_num == new_num:\n'
        '        return 0\n'
        '    ts_now = rt.now_str()\n'
