        '        for row in rows:\n'
        '            order = _row_to_order_dict(row)\n'
        '            changed = False\n'
        '            if safe_int(order.get("service_number")) == old_num:\n'
        '                order["service_number"] = new_num\n'
        '                changed = True\n'
        '            if safe_int(order.get("panel_add_service_number")) == old_num:\n'
        '                order["panel_add_service_number"] = new_num\n'
        '                changed = True\n'
        '            if not changed:\n'
        '                continue\n'
        '            order["updated_at"] = ts_now\n'
