        '\n'
        '\n'
        'class _DynamicDbLock:\n'
        '    """Reentrant lock proxy resolving db.get_db_lock() dynamically for the active rt.DB_PATH."""\n'
        '\n'
        '    def __init__(self) -> None:\n'
        '        self._local = threading.local()\n'
        '\n'
        '    def acquire(self, blocking: bool = True, timeout: float = -1) -> bool:\n'
        '        target_lock = db.get_db_lock()\n'
        '        acquired = (\n'
        '            target_lock.acquire(blocking=blocking)\n'
        '            if timeout == -1\n'
        '            else target_lock.acquire(blocking=blocking, timeout=timeout)\n'
        '        )\n'
        '        if acquired:\n'
        '            stack = getattr(self._local, "stack", None)\n'
        '            if stack is None:\n'
        '                stack = []\n'
        '                self._local.stack = stack\n'
        '            stack.append(target_lock)\n'
        '        return acquired\n'
        '\n'
        '    def release(self) -> None:\n'
        '        stack = getattr(self._local, "stack", None)\n'
        '        if not stack:\n'
        '            raise RuntimeError("cannot release un-acquired lock")\n'
        '        target_lock = stack.pop()\n'
        '        target_lock.release()\n'
        '\n'
        '    def __enter__(self) -> "_DynamicDbLock":\n'
        '        self.acquire()\n'
        '        return self\n'
        '\n'
        '    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> None:\n'
        '        self.release()\n'
        '\n'
        '    def _is_owned(self) -> bool:\n'
        '        stack = getattr(self._local, "stack", None)\n'
        '        if stack:\n'
        '            return stack[-1]._is_owned()\n'
        '        return db.get_db_lock()._is_owned()\n'
        '\n'
        '\n'
        'CONFIG_LOCK = threading.RLock()\n'
        'ORDERS_LOCK = _DynamicDbLock()\n'
        'STATE_LOCK = _DynamicDbLock()\n'
        'VALID_LINKS_MIGRATION_STATE_KEY = "valid_links_defaults_migrated"\n'
        '\n'
        '_PATH_LOCKS_GUARD = threading.Lock()\n'
        '_PATH_LOCKS: Dict[str, threading.RLock] = {}\n'
        '\n'
        '\n'
        'def _get_path_lock(path: str) -> threading.RLock:\n'
        '    """Return a per-file reentrant lock so concurrent writers never collide on os.replace."""\n'
        '    key = os.path.normcase(os.path.abspath(path))\n'
        '    with _PATH_LOCKS_GUARD:\n'
        '        lock = _PATH_LOCKS.get(key)\n'
        '        if lock is None:\n'
        '            lock = threading.RLock()\n'
        '            _PATH_LOCKS[key] = lock\n'
        '        return lock\n'
        '\n'
        '\n'
        'def _make_temp_path(path: str) -> str:\n'
        '    """Build a collision-free temporary file path in the target directory."""\n'
        '    return f"{path}.{os.getpid()}.{threading.get_ident()}.{uuid.uuid4().hex[:8]}.tmp"\n'
        '\n'
        '\n'
        'def _replace_with_retry(temp_path: str, abs_path: str, attempts: int = 5) -> None:\n'
        '    """Retry os.replace briefly on transient Windows sharing/permission locks."""\n'
        '    for attempt in range(attempts):\n'
        '        try:\n'
        '            os.replace(temp_path, abs_path)\n'
        '            return\n'
        '        except PermissionError:\n'
        '            if attempt + 1 >= attempts:\n'
        '                raise\n'
        '            time.sleep(0.01 * (attempt + 1))\n'
        '\n'
        '\n'
        'def _write_bytes_atomic(path: str, raw_bytes: bytes) -> None:\n'
        '    """Atomically write raw bytes using a unique temp file, flush/fsync, and os.replace."""\n'
        '    abs_path = os.path.abspath(path)\n'
        '    parent = os.path.dirname(abs_path)\n'
        '    if parent:\n'
        '        os.makedirs(parent, exist_ok=True)\n'
        '    temp_path = _make_temp_path(abs_path)\n'
        '    with _get_path_lock(abs_path):\n'
        '        try:\n'
        '            with open(temp_path, "wb") as fh:\n'
        '                fh.write(raw_bytes)\n'
        '                fh.flush()\n'
        '                os.fsync(fh.fileno())\n'
        '            _replace_with_retry(temp_path, abs_path)\n'
        '        finally:\n'
        '            if os.path.exists(temp_path):\n'
        '                try:\n'
        '                    os.remove(temp_path)\n'
        '                except OSError as exc:\n'
        '                    logger.debug(f"Не удалось удалить временный файл {temp_path}: {exc}")\n'
        '\n'
        '\n'
        'def _write_json_atomic(path: str, data: Any) -> None:\n'
        '    """Atomically persist JSON using UTF-8 serialization and atomic byte replacement."""\n'
        '    encoded = json.dumps(data, indent=4, ensure_ascii=False).encode("utf-8")\n'
        '    _write_bytes_atomic(path, encoded)\n'
        '\n'
        '\n'
        'def _safe_load_json(path: str, default: Any) -> Any:\n'
        '    """Load JSON safely, archiving corrupt files instead of crashing."""\n'
        '    if not os.path.exists(path):\n'
        '        return default\n'
        '    try:\n'
        '        with open(path, "r", encoding="utf-8") as fh:\n'
        '            return json.load(fh)\n'
        '    except json.JSONDecodeError as exc:\n'
        '        logger.error(f"Ошибка при чтении {os.path.basename(path)}: {exc}")\n'
        '        backup_path = f"{path}.bak.{int(time.time())}"\n'
        '        try:\n'
        '            shutil.copy2(path, backup_path)\n'
        '            logger.info(f"Создана резервная копия поврежденного файла: {backup_path}")\n'
        '        except OSError as bak_exc:\n'
        '            logger.error(f"Не удалось создать резервную копию {os.path.basename(path)}: {bak_exc}")\n'
        '        return default\n'
        '    except OSError as exc:\n'
        '        logger.error(f"Ошибка при чтении {os.path.basename(path)}: {exc}")\n'
        '        return default\n'
        '\n'
        '\n'
        'def _safe_write_json(path: str, data: Any) -> bool:\n'
        '    """Write JSON atomically and return explicit success status."""\n'
        '    try:\n'
        '        _write_json_atomic(path, data)\n'
        '        return True\n'
        '    except (OSError, TypeError, ValueError) as exc:\n'
        '        logger.exception(f"Ошибка при сохранении {os.path.basename(path)}: {exc}")\n'
        '        return False\n'
        '\n'
        '\n'
        'def _sync_runtime_config_refs(cfg: Any) -> None:\n'
        '    if not isinstance(cfg, dict):\n'
