        '            logger.debug(f"Файл конфигурации {rt.CONFIG_PATH} не найден. Проверяем резервную копию.")\n'
        '\n'
        '        if (not isinstance(raw_data, dict) or not raw_data) and os.path.exists(rt.CONFIG_BAK_PATH):\n'
        '            try:\n'
        '                if os.path.getsize(rt.CONFIG_BAK_PATH) > 0:\n'
        '                    logger.warning(f"Попытка восстановить конфиг из резервной копии {rt.CONFIG_BAK_PATH}...")\n'
        '                    with open(rt.CONFIG_BAK_PATH, "r", encoding="utf-8") as fh:\n'
        '                        bak_content = fh.read().strip()\n'
