        '\n'
        '        if not isinstance(raw_data, dict) or not raw_data:\n'
        '            corrupt_path = f"{rt.CONFIG_PATH}.corrupt_{int(time.time())}"\n'
        '            if os.path.exists(rt.CONFIG_PATH):\n'
