        '\n'
        '\n'
        'def register_navigation_prefix(prefix: str, handler: Callable[[types.CallbackQuery, str], Any]) -> None:\n'
        '    """Register a prefix-matched callback navigation destination."""\n'
        '    clean_prefix = str(prefix)\n'
        '    for idx, (existing_prefix, _) in enumerate(_NAVIGATION_PREFIXES):\n'
        '        if existing_prefix == clean_prefix:\n'
        '            _NAVIGATION_PREFIXES[idx] = (clean_prefix, handler)\n'
        '            return\n'
        '    _NAVIGATION_PREFIXES.append((clean_prefix, handler))\n'
        '\n'
        '\n'
        'def _dispatch_navigation_callback(call: types.CallbackQuery, target: str) -> None:\n'
