        '    handler = _NAVIGATION_TARGETS.get(target)\n'
        '    if handler is not None:\n'
        '        handler(call)\n'
        '        return\n'
        '    for prefix, prefix_handler in _NAVIGATION_PREFIXES:\n'
        '        if target.startswith(prefix):\n'
        '            prefix_handler(call, target)\n'
        '            return\n'
        '    fallback = _NAVIGATION_TARGETS.get("asmm:return_to_settings")\n'
        '    if fallback is not None:\n'
        '        fallback(call)\n'
