        '\n'
        'def _is_step_sender_allowed(message: Any, expected_user_id: Optional[int]) -> bool:\n'
        '    sender = getattr(message, "from_user", None)\n'
        '    sender_id = getattr(sender, "id", None)\n'
        '    if expected_user_id is not None and sender_id != expected_user_id:\n'
        '        return False\n'
        '    if sender_id is None:\n'
        '        tg = getattr(rt.cardinal_instance, "telegram", None)\n'
        '        auth_users = getattr(tg, "authorized_users", None)\n'
