        '\n'
        '\n'
        'def _register_guarded_step_handler(\n'
        '    anchor_message: Any,\n'
        '    next_handler: Any,\n'
        '    *handler_args: Any,\n'
        '    expected_user_id: Optional[int] = None,\n'
        '    allowed_commands: Optional[Any] = None,\n'
        ') -> None:\n'
        '    allowed = {\n'
        '        str(cmd).strip().lower()\n'
        '        for cmd in (allowed_commands or getattr(next_handler, "allowed_step_commands", ()) or ())\n'
        '        if str(cmd).strip()\n'
        '    }\n'
        '\n'
        '    def _guarded_step(message: types.Message) -> Any:\n'
        '        if not _is_step_sender_allowed(message, expected_user_id):\n'
        '            sender_id = getattr(getattr(message, "from_user", None), "id", None)\n'
        '            rt.logger.warning(\n'
        '                f"[TG STEP IGNORED] chat_id={getattr(getattr(message, \'chat\', None), \'id\', None)}, "\n'
        '                f"expected_user={expected_user_id}, actual_user={sender_id}"\n'
        '            )\n'
        '            rt.bot.register_next_step_handler(message, _guarded_step)\n'
        '            return None\n'
        '        raw_text = getattr(message, "text", None)\n'
        '        if isinstance(raw_text, str) and raw_text.lstrip().startswith("/"):\n'
        '            cmd_token = raw_text.lstrip().split(None, 1)[0].split("@", 1)[0].lower()\n'
        '            if cmd_token not in allowed:\n'
        '                chat_id = getattr(getattr(message, "chat", None), "id", None)\n'
        '                sender_id = getattr(getattr(message, "from_user", None), "id", None)\n'
        '                if chat_id is not None:\n'
        '                    _clear_step_handler(chat_id)\n'
        '                    _clear_navigation_states(chat_id)\n'
        '                _clear_tg_state(chat_id, sender_id)\n'
        '                return None\n'
        '        return next_handler(message, *handler_args)\n'
        '\n'
        '    rt.bot.register_next_step_handler(anchor_message, _guarded_step)\n'
        '\n'
        '\n'
        'def _encode_callback_value(prefix: str, raw_value: str, *, max_bytes: int = 64) -> str:\n'
        '    value = str(raw_value or "")\n'
        '    full = f"{prefix}{value}"\n'
        '    if len(full.encode("utf-8")) <= max_bytes and not value.startswith("t_"):\n'
        '        return full\n'
        '    digest = hashlib.sha256(value.encode("utf-8")).hexdigest()[:12]\n'
        '    token = f"t_{digest}"\n'
        '    with _CALLBACK_TOKENS_LOCK:\n'
        '        if token in rt.CALLBACK_TOKENS:\n'
        '            rt.CALLBACK_TOKENS.pop(token, None)\n'
        '        while len(rt.CALLBACK_TOKENS) >= _CALLBACK_TOKENS_MAX:\n'
        '            oldest_key = next(iter(rt.CALLBACK_TOKENS))\n'
        '            rt.CALLBACK_TOKENS.pop(oldest_key, None)\n'
        '        rt.CALLBACK_TOKENS[token] = value\n'
        '    return f"{prefix}{token}"\n'
        '\n'
        '\n'
        'def _decode_callback_value(raw_arg: str) -> str:\n'
        '    arg = str(raw_arg or "")\n'
        '    if arg.startswith("t_"):\n'
        '        with _CALLBACK_TOKENS_LOCK:\n'
        '            return str(rt.CALLBACK_TOKENS.get(arg) or "")\n'
        '    return arg\n'
        '\n'
        '\n'
        'def _start_ui_input_flow(\n'
