        '\n'
        '\n'
        'def _set_tg_state(\n'
        '    chat_id: int,\n'
        '    message_id: int,\n'
        '    user_id: int,\n'
        '    state: str,\n'
        '    data: Optional[Dict[str, Any]] = None,\n'
        ') -> None:\n'
        '    tg = getattr(rt.cardinal_instance, "telegram", None)\n'
        '    set_state = getattr(tg, "set_state", None)\n'
        '    if callable(set_state):\n'
        '        try:\n'
