        '        except Exception as exc:\n'
        '            rt.logger.debug(f"set_state({chat_id}, {user_id}, {state}) failed: {exc}")\n'
        '\n'
        '\n'
        'def _clear_tg_state(chat_id: Optional[int], user_id: Optional[int]) -> None:\n'
        '    if chat_id is None or user_id is None:\n'
        '        return\n'
        '    tg = getattr(rt.cardinal_instance, "telegram", None)\n'
        '    clear_state = getattr(tg, "clear_state", None)\n'
        '    if callable(clear_state):\n'
