        '\n'
        'def _build_return_to_lots_callback(chat_id: int) -> str:\n'
        '    return f"asmm:return_to_lots_{_get_lot_page_context(chat_id)}"\n'
        '\n'
        '\n'
        'def _build_lot_input_keyboard() -> InlineKeyboardMarkup:\n'
        '    kb_ = InlineKeyboardMarkup(row_width=1)\n'
        '    kb_.add(InlineKeyboardButton("◀️ Назад", callback_data="asmm:lot_input_back"))\n'
        '    return kb_\n'
        '\n'
        '\n'
        'def _decode_prefixed_lot_key(call: types.CallbackQuery, prefix: str) -> str:\n'
        '    data = str(getattr(call, "data", "") or "")\n'
        '    raw_arg = data.split(prefix, 1)[1] if prefix in data else ""\n'
        '    return _decode_callback_value(raw_arg)\n'
        '\n'
        '\n'
        'def _show_lot_card(\n'
        '    chat_id: int,\n'
        '    lot_key: str,\n'
        '    message_id: Optional[int] = None,\n'
        '    back_callback: Optional[str] = None,\n'
        '    back_label: Optional[str] = None,\n'
        ') -> None:\n'
        '    cfg = load_config()\n'
        '    lot_map = cfg.get("lot_mapping", {})\n'
        '    if lot_key not in lot_map:\n'
        '        text_ = f"❌ Лот {h(lot_key)} не найден."\n'
        '        fallback_back = back_callback or _build_return_to_lots_callback(chat_id)\n'
        '        kb_missing = _inline_kb((back_label or "◀️ Назад", fallback_back))\n'
        '        if message_id is not None:\n'
        '            _safe_edit_message_text(text_, chat_id, message_id, parse_mode="HTML", reply_markup=kb_missing)\n'
        '        else:\n'
        '            rt.bot.send_message(chat_id, text_, parse_mode="HTML", reply_markup=kb_missing)\n'
        '        return\n'
        '\n'
        '    if not back_callback:\n'
        '        back_callback = _build_return_to_lots_callback(chat_id)\n'
        '    if not back_label:\n'
        '        back_label = "◀️ К списку" if str(back_callback).startswith("asmm:return_to_lots") else "◀️ Назад"\n'
        '\n'
        '    _set_lot_card_context(chat_id, lot_key, back_callback, back_label)\n'
        '\n'
        '    ld_ = lot_map[lot_key]\n'
        '    fallback_number = _not_configured(ld_.get("fallback_service_number"))\n'
