        '    cur_fmt = ld_.get("link_format", "as_is")\n'
        '    link_format_labels = {\n'
        '        "as_is": "Как введено (ссылка / юзер)",\n'
        '        "clean_username": "Только username (без @)",\n'
        '        "username_at": "Только username (@handle)",\n'
        '        "full_url": "Полная ссылка (https://...)",\n'
        '    }\n'
        '    cur_fmt_label = link_format_labels.get(cur_fmt, "Как введено")\n'
        '\n'
        '    txt_ = "\\n".join([\n'
        '        f"<b>{h(lot_key)}</b>",\n'
