        '        "<b>Название:</b>",\n'
        '        h(ld_.get("name") or "Без названия"),\n'
        '        "",\n'
        '        f"Номер панели: <code>{h(ld_.get(\'service_number\', 1))}</code>",\n'
        '        f"ID услуги: <code>{h(ld_.get(\'service_id\', \'—\'))}</code>",\n'
        '        f"Кол-во: <code>{h(ld_.get(\'quantity\', \'—\'))}</code>",\n'
        '        f"Формат для панели: <code>{h(cur_fmt_label)}</code>",\n'
