        '    if has_fallback:\n'
        '        buttons.append(InlineKeyboardButton("❌ Сбросить резервную панель", callback_data=_encode_callback_value("asmm:clear_fallback_", lot_key)))\n'
        '    buttons.extend([\n'
        '        InlineKeyboardButton("❌ Удалить лот", callback_data=_encode_callback_value("asmm:delete_one_lot_", lot_key)),\n'
        '        InlineKeyboardButton(back_label, callback_data=back_callback),\n'
        '    ])\n'
        '\n'
        '    kb_ = InlineKeyboardMarkup(row_width=1)\n'
        '    for btn in buttons:\n'
        '        kb_.add(btn)\n'
        '\n'
        '    if message_id is not None:\n'
        '        _safe_edit_message_text(txt_, chat_id, message_id, parse_mode="HTML", reply_markup=kb_)\n'
        '    else:\n'
        '        rt.bot.send_message(chat_id, txt_, parse_mode="HTML", reply_markup=kb_)\n'
        '\n'
        '\n'
        'def cycle_link_fmt_callback(call: types.CallbackQuery) -> None:\n'
        '    chat_id, message_id, _ = _extract_call_ids(call)\n'
        '    if chat_id is None:\n'
        '        _safe_answer_callback(call)\n'
        '        return\n'
        '    lot_key = _decode_prefixed_lot_key(call, "asmm:cycle_link_fmt_")\n'
        '    order_formats = ["as_is", "clean_username", "username_at", "full_url"]\n'
        '    format_short_names = {\n'
        '        "as_is": "Как введено",\n'
        '        "clean_username": "Только username",\n'
        '        "username_at": "Username (@...)",\n'
        '        "full_url": "Полная ссылка",\n'
