        '        if lot_key in lot_map:\n'
        '            current_fmt = lot_map[lot_key].get("link_format", "as_is")\n'
        '            next_idx = (order_formats.index(current_fmt) + 1) % len(order_formats) if current_fmt in order_formats else 0\n'
        '            new_fmt = order_formats[next_idx]\n'
        '            lot_map[lot_key]["link_format"] = new_fmt\n'
        '            cfg["lot_mapping"] = lot_map\n'
        '            save_config(cfg)\n'
        '\n'
        '    if new_fmt is None:\n'
        '        _safe_answer_callback(call, "❌ Лот не найден")\n'
        '        return\n'
        '\n'
        '    _safe_answer_callback(call, f"Формат: {format_short_names.get(new_fmt, new_fmt)}")\n'
        '    card_ctx = _get_lot_card_context(chat_id) or {}\n'
        '    _show_lot_card(\n'
        '        chat_id,\n'
        '        lot_key,\n'
        '        message_id,\n'
        '        back_callback=card_ctx.get("back_callback"),\n'
        '        back_label=card_ctx.get("back_label"),\n'
        '    )\n'
        '\n'
        '\n'
        'def _start_lot_edit_flow(call: types.CallbackQuery, lot_key: str, mode: str, prompt_text: str, next_handler: Any) -> None:\n'
        '    chat_id, message_id, initiator_user_id = _extract_call_ids(call)\n'
        '    if chat_id is None:\n'
        '        return\n'
        '    _clear_step_handler(chat_id)\n'
        '    _clear_ui_input_state(chat_id)\n'
        '    _set_lot_input_state(chat_id, lot_key, mode, prompt_text, next_handler, initiator_user_id=initiator_user_id)\n'
        '    if message_id is not None:\n'
        '        msg_ = _safe_edit_message_text(\n'
        '            prompt_text,\n'
        '            chat_id,\n'
        '            message_id,\n'
        '            parse_mode="HTML",\n'
        '            reply_markup=_build_lot_input_keyboard(),\n'
        '        ) or call.message\n'
        '    else:\n'
        '        msg_ = rt.bot.send_message(\n'
        '            chat_id,\n'
        '            prompt_text,\n'
