        '    )\n'
        '    _register_guarded_step_handler(msg_, next_handler, lot_key, expected_user_id=initiator_user_id)\n'
        '\n'
        '\n'
        'def lot_input_back_callback(call: types.CallbackQuery) -> None:\n'
        '    _safe_answer_callback(call)\n'
        '    chat_id, message_id, _ = _extract_call_ids(call)\n'
