        '    _register_guarded_step_handler, _repeat_ui_input_flow, _safe_answer_callback, _safe_edit_message_text,\n'
        '    _send_or_edit_text, _set_delete_confirm_grace, _start_ui_input_flow, clean_tg_text, h,\n'
        '    register_navigation_prefix, register_navigation_target,\n'
        ')\n'
        'from .telemetry import _show_telemetry_gate\n'
        '\n'
        '\n'
