        '\n'
        'def _open_main_settings_menu(chat_id: int, message_id: Optional[int] = None) -> None:\n'
        '    if not _telemetry_consent_accepted():\n'
        '        _remember_telemetry_chat_id(chat_id)\n'
        '    cfg = load_config()\n'
        '    txt_, kb = build_main_menu_text_and_kb(cfg)\n'
        '    target_msg_id = _send_or_edit_text(chat_id, txt_, kb, message_id=message_id)\n'
        '    if target_msg_id is None or not (cfg.get("services") or {}):\n'
        '        return\n'
        '    expected_rev = (\n'
        '        rt.bump_screen_revision(chat_id, target_msg_id)\n'
        '        if message_id is None\n'
        '        else rt.get_screen_revision(chat_id, target_msg_id)\n'
