        '                lambda: build_main_menu_text_and_kb(load_config()),\n'
        '                parse_mode="HTML",\n'
        '            )\n'
        '            if updated\n'
        '            else None\n'
        '        ),\n'
        '    )\n'
        '\n'
        '\n'
        'def build_main_menu_text_and_kb(cfg: Dict[str, Any]) -> Tuple[str, InlineKeyboardMarkup]:\n'
        '    """Собирает главное меню AutoSMM."""\n'
        '    lmap = cfg.get("lot_mapping", {}) or {}\n'
        '    auto_refunds_icon = "✅" if cfg.get("auto_refunds", False) else "❌"\n'
        '    confirm_link_icon = "✅" if cfg.get("confirm_link", True) else "❌"\n'
        '    fallback_icon = "✅" if cfg.get("fallback_enabled", False) else "❌"\n'
        '\n'
        '    stats = analytics.get_statistics()\n'
        '    day_profit = stats.get("day_chistota", 0) if stats else 0\n'
