        '        f"🚀 <b>AutoSMM v{h(rt.VERSION)}</b>",\n'
        '        "",\n'
        '        "━━━━━━━━━━━━━━━━━━━━━",\n'
        '        "",\n'
        '        f"📦 <b>Лоты:</b> <code>{h(len(lmap))}</code>",\n'
        '        "",\n'
        '        f"<b>Автовозвраты:</b> {auto_refunds_icon}",\n'
        '        f"<b>Подтверждение ссылки:</b> {confirm_link_icon}",\n'
        '        f"<b>Резервная панель:</b> {fallback_icon}",\n'
        '        "",\n'
        '        f"💰 <b>Профит за 24ч:</b> <code>{h(day_profit_fmt)} ₽</code>",\n'
