class _AutoSMMLoader(importlib.abc.Loader):
    """Execute a bundled source module inside its isolated virtual package."""

    def __init__(self, mod_name: str, source: str, is_pkg: bool) -> None:
        self._mod_name = mod_name
        self._source = source
        self._is_pkg = is_pkg

    def create_module(self, spec):
        return None

    def exec_module(self, module) -> None:
        module.__file__ = _ENTRY_FILE
        if self._is_pkg:
            module.__path__ = []
            module.__package__ = module.__name__
        else:
            module.__package__ = module.__name__.rpartition(".")[0]
        filename = f"{_ENTRY_FILE}::<{_BUNDLE_PKG}.{self._mod_name}>"
        code = compile(self._source, filename, "exec")
        exec(code, module.__dict__)


class _AutoSMMFinder(importlib.abc.MetaPathFinder):
    """Resolve imports for the virtual _autosmm_src package tree."""

    _autosmm_bundle_id = _BUNDLE_PKG

    def find_spec(self, fullname: str, path=None, target=None):
        if fullname == _BUNDLE_PKG:
            mod_key = "__init__"
            is_pkg = True
        elif fullname.startswith(f"{_BUNDLE_PKG}."):
            sub_name = fullname[len(_BUNDLE_PKG) + 1:]
            pkg_key = f"{sub_name}.__init__"
            if pkg_key in _BUNDLE_SOURCES:
                mod_key = pkg_key
                is_pkg = True
            elif sub_name in _BUNDLE_SOURCES:
                mod_key = sub_name
                is_pkg = False
            else:
                return None
        else:
            return None
        source = _BUNDLE_SOURCES.get(mod_key)
        if source is None:
            return None
        loader = _AutoSMMLoader(mod_key, source, is_pkg)
        return importlib.util.spec_from_loader(
            fullname,
            loader,
            origin=_ENTRY_FILE,
            is_package=is_pkg,
        )


def _bootstrap_bundle():
    """Reset any prior _autosmm_src state and load _autosmm_src.plugin."""
    sys.meta_path[:] = [
        finder
        for finder in sys.meta_path
        if getattr(finder, "_autosmm_bundle_id", None) != _BUNDLE_PKG
    ]
    prefix = f"{_BUNDLE_PKG}."
    for name in list(sys.modules):
        if name == _BUNDLE_PKG or name.startswith(prefix):
            sys.modules.pop(name, None)
    sys.meta_path.insert(0, _AutoSMMFinder())
    return importlib.import_module(f"{_BUNDLE_PKG}.plugin")


_entry_mod = _bootstrap_bundle()
for _attr in dir(_entry_mod):
    if not (_attr.startswith("__") and _attr.endswith("__")):
        globals()[_attr] = getattr(_entry_mod, _attr)
del _attr
